export function slugifyTerm(term) {
  return term.toLowerCase()
    .replace(/ą/g,'a').replace(/ć/g,'c').replace(/ę/g,'e')
    .replace(/ł/g,'l').replace(/ń/g,'n').replace(/ó/g,'o')
    .replace(/ś/g,'s').replace(/ź/g,'z').replace(/ż/g,'z')
    .replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')
}

export const DICTIONARY_TERMS = [
  // === CNM / POLIAMORIA ===
  { term: 'CNM (Consensual Non-Monogamy)', slug: 'cnm', definition: 'CNM to parasol, pod którym mieści się wszystko co nie jest klasyczną monogamią — ale dzieje się za wiedzą i zgodą wszystkich zaangażowanych. Innymi słowy: nie chodzi o zdradę, chodzi o wybranie innego modelu. Obejmuje polyamorię, swinging, otwarte związki, DADT i dziesiątki innych konfiguracji. Klucz to słowo "consensual" — wszyscy wiedzą, wszyscy się zgadzają, nikt nie jest zaskoczony. CNM praktykuje szacunkowo kilka procent dorosłych, choć wielu robi to po cichu, bez etykiety. Nie ma jednego "właściwego" sposobu na CNM — to jak pizza, każdy układa swoje składniki. Wbrew obawom, badania pokazują że ludzie w CNM mają podobny poziom satysfakcji ze związku co monogamiści. Podstawowe narzędzie: komunikacja. Dużo komunikacji. Prawdopodobnie więcej niż myślisz.', category: 'CNM / Poliamoria', examples: ['CNM to szerokie pojęcie — klucz to zgoda i komunikacja, nie konkretna forma związku.'] },
  { term: 'ENM (Ethical Non-Monogamy)', slug: 'enm', definition: 'ENM to synonim CNM — używane zamiennie, zależnie od tego kogo pytasz. Słowo "ethical" (etyczna) ma podkreślać że to nie jest tylko "rób co chcesz" — tu chodzi o uczciwość, przejrzystość i szacunek dla wszystkich osób w układzie. Ktoś wymyślił ENM żeby odciąć się od skojarzeń z niewiernością i chaosem. Jeśli CNM brzmi technicznie, ENM brzmi bardziej jak deklaracja wartości. W praktyce: te same rzeczy, inna etykieta na opakowaniu. Część osób woli "CNM" bo brzmi neutralnie, inni wolą "ENM" bo podkreśla intencje. W rozmowie możesz używać obu — nikt Cię nie poprawi.', category: 'CNM / Poliamoria', examples: ['ENM kładzie nacisk na uczciwość — dlatego "ethical" w nazwie.'] },
  { term: 'Poliamoria', slug: 'poliamoria', definition: 'Poliamoria to zdolność i chęć kochania więcej niż jednej osoby jednocześnie — i robienie tego otwarcie, za wiedzą wszystkich. Różni się od swingingu tym, że chodzi nie tylko o seks, ale też o emocje, przywiązanie, może wspólne życie. Nazwa pochodzi z greckiego "poly" (wiele) i łacińskiego "amor" (miłość) — lingwistyczny miszmasz, który jakoś się przyjął. Wbrew popularnemu mitowi, polyamoria nie oznacza że kochasz każdego tak samo — każda relacja jest inna, tak jak są różni ludzie. Często słyszysz "ale jak możesz kochać więcej niż jedną osobę?" — to jak pytać rodzica czy mniej kocha drugie dziecko bo urodziło się pierwsze. Miłość nie jest pizzą do podziału na kawałki. Polyamoria wymaga dużo komunikacji, samoświadomości i czasu — to nie jest łatwiejsze niż monogamia, po prostu inne.', category: 'CNM / Poliamoria', examples: ['Ania jest w związku z Markiem od 5 lat i od roku spotyka się też z Kasią. Wszyscy o tym wiedzą i się wspierają.'] },
  { term: 'Otwarty związek', slug: 'otwarty-zwiazek', definition: 'W otwartym związku para ma główną relację emocjonalną i romantyczną tylko ze sobą — ale seks z innymi osobami jest ok. Emocje zostają w domu, ciało może podróżować. To jedna z najbardziej popularnych form CNM, często pierwsza próba dla par które chcą "otworzyć" związek. Kluczowe pytanie do ustalenia na początku: co dokładnie jest "otwarte"? Czy mogą być randki? Czy nocowanie u kogoś innego jest ok? Czy w twoim mieście, czy tylko w delegacji? Każda para ustala własne zasady — nie ma jednego wzorca. Częsty błąd: para otwiera związek licząc że rozwiąże to inne problemy. Nie rozwiązuje — raczej amplifikuje to co już jest. Jeśli związek jest zdrowy, może być fajną przygodą.', category: 'CNM / Poliamoria', examples: ['W otwartym związku można mieć przygody, ale romantyczne zaangażowanie zostaje w parze.'] },
  { term: 'Polyfidelity / Poliwierność', slug: 'polyfidelity', definition: 'Polyfidelity to zamknięta grupa ludzi — na przykład trójka lub czwórka — którzy są razem nawzajem i tylko ze sobą. Brzmi paradoksalnie: "wierna poliamoria"? Tak, dokładnie. Myśl o tym jak o monogamii, tylko rozszerzonej na więcej osób. Wszyscy w grupie wiedzą o wszystkich, wszyscy są ze wszystkimi, nikt nie szuka niczego "na zewnątrz" bez rozmowy z resztą. To jedna z bardziej stabilnych konfiguracji CNM — jeśli dynamika grupowa działa. Wymaga dużo wzajemnego zaufania i jasnych rozmów o tym co się dzieje gdy ktoś chce poszerzyć grupę. Popularne wśród ludzi którzy chcą bliskości i zaangażowania, ale nie są przekonani do klasycznej pary. Trójki i czwórki polyfidelity istnieją od dekad — po prostu rzadko o tym mówią głośno.', category: 'CNM / Poliamoria', examples: ['Adam, Ewa i Tomek są razem od 3 lat. To ich zamknięta trójka.'] },
  { term: 'Compersion', slug: 'compersion', definition: 'Compersion to uczucie radości i ciepła które czujesz widząc że Twój partner jest szczęśliwy z kimś innym. Często opisywane jako "przeciwieństwo zazdrości" — choć to nie do końca precyzyjne, bo można mieć jednocześnie i jedno, i drugie. Słowo nie istnieje w słowniku polskim ani angielskim — wymyśliła je społeczność poly w latach 90. i się przyjęło. Brzmi abstrakcyjnie dopóki tego nie poczujesz — wtedy nagle rozumiesz dlaczego people in poly są tak podekscytowani tym słowem. Compersion nie jest obowiązkowe ani "dowodem" że jesteś "dobry w poly" — niektórzy nigdy tego nie czują i to też jest ok. Jeśli Twój partner wraca ze szczęśliwą miną z randki i Ty czujesz się z tym dobrze albo wręcz cieszysz — właśnie to jest compersion. Bywa mylone z brakiem uczuć, ale to coś zupełnie innego: to aktywna, pozytywna emocja, nie obojętność.', category: 'CNM / Poliamoria', examples: ['Widzisz że Twoja dziewczyna świetnie się bawi na randce z kimś innym i czujesz radość zamiast zazdrości — to compersion.'] },
  { term: 'NRE (New Relationship Energy)', slug: 'nre', definition: 'NRE to ta intensywna, rozedrgana faza na początku nowej relacji — kiedy non-stop myślisz o tej osobie, wszystko wydaje się idealne, seks jest niesamowity i masz wrażenie że wreszcie rozumiesz o co chodzi w życiu. To biochemia: dopamina, oksytocyna i adrenalina robią swoje. Trwa zwykle od kilku miesięcy do półtora roku, potem opada — i to jest normalne, nie oznacza że związek umiera. W CNM NRE jest szczególnie ważne bo gdy partner wchodzi w nową relację, jego energia i czas mogą się przesunąć w tamtą stronę. Dla osób z boku może to boleć — nawet jeśli rozumiesz to racjonalnie, emocje mają swoje zdanie. Dobra praktyka: mów partnerowi gdy czujesz że NRE go "wciąga" kosztem Waszego czasu. Warto też pamiętać że osoby w NRE mają tendencję do podejmowania impulsywnych decyzji — wstrzymaj się z dużymi zobowiązaniami dopóki mgła nie opadnie.', category: 'CNM / Poliamoria', examples: ['W fazie NRE wszystko wydaje się idealne — warto zachować zdrowy rozsądek i rozmawiać z partnerem.'] },
  { term: 'Metamour', slug: 'metamour', definition: 'Metamour to partner Twojego partnera — osoba z którą nie jesteś w relacji romantycznej, ale jesteście połączeni przez kogoś wspólnego. Jeśli jesteś z Anią, a Ania jest też z Tomkiem — Tomek jest Twoim metamourem. Nie musicie być przyjaciółmi, nie musicie się lubić, choć miło gdy tak jest. Relacja z metamourem może być wszystkim: od "hej, cześć" przez SMS po prawdziwa przyjaźń i wspólne obiady. W kitchen table poly metamours się znają i lubią. W parallel poly możesz nawet nie znać ich imienia. Wiele osób odkrywa że metamourowie są całkiem fajnymi ludźmi — w końcu mają dobry gust, skoro wybrali tego samego partnera co Ty. Słowo pochodzi ze środowiska poly anglojęzycznego i nie ma dobrego polskiego odpowiednika — "partner partnera" brzmi jak łamigłówka, więc metamour zostaje.', category: 'CNM / Poliamoria', examples: ['Mój metamour i ja lubimy wspólnie gotować, choć nie jesteśmy parą.'] },
  { term: 'Polycule', slug: 'polycule', definition: 'Polycule to cała sieć osób połączonych relacjami poliamorycznymi — bezpośrednio lub pośrednio. Nazwa pochodzi od "molecule" — tak jak atomy w cząsteczce, ludzie są połączeni różnymi wiązaniami. Ty jesteś z Anią, Ania jest z Tomkiem, Tomek jest z Kasią i Piotrem — to jest jeden polycule. Konfiguracje bywają skomplikowane jak diagram chemiczny i niektórzy naprawdę rysują schematy żeby się nie pogubić. Polycule może być małe (trzy osoby) albo rozrastać się do kilkunastu gdy relacje się splatają przez lata. Nie wszyscy w polycule muszą się znać ani lubić — ale zazwyczaj jest jakaś świadomość że "należymy do tej samej sieci". W środowisku poly słyszysz czasem "mój polycule" z prawdziwą dumą — to jak powiedzieć "moja rodzina", tyle że z wyboru.', category: 'CNM / Poliamoria', examples: ['Ty jesteś z Anią, Ania jest z Tomkiem, Tomek jest z Kasią — to jest Twój polycule.'] },
  { term: 'Unicorn', slug: 'unicorn', definition: 'Unicorn to biseksualna kobieta gotowa dołączyć do istniejącej pary hetero (mężczyzna + kobieta) jako "trzecia" — i być z obojgiem jednocześnie, na ich warunkach. Nazwa pochodzi stąd że taka osoba jest rzadka jak jednorożec — i słusznie, bo oczekiwania par bywają nierealistyczne. Para często szuka kogoś kto będzie "pasował idealnie" do obu, nie będzie miał własnych potrzeb emocjonalnych, nie zagrozi ich związkowi i zniknie gdy para zdecyduje. Unicorny z kolei są pełnoprawnymi ludźmi z własnym życiem, uczuciami i oczekiwaniami — co często zaskakuje pary szukające "dodatku". Termin bywa używany przez same te kobiety z humorem i dystansem, czasem z rozmysłem jako self-identifier. Jeśli szukasz unicorna — zanim wyślesz kolejne ogłoszenie, zastanów się co możesz zaoferować tej osobie, nie tylko czego oczekujesz.', category: 'CNM / Poliamoria', examples: ['Wiele par szuka unicorna, ale warto pamiętać o podmiotowości takiej osoby.'] },
  { term: 'Unicorn Hunting', slug: 'unicorn-hunting', definition: 'Unicorn hunting to aktywne poszukiwanie przez parę biseksualnej kobiety do trójkąta — i niestety często w sposób który nie uwzględnia jej jako pełnoprawnego uczestnika. Red flags w ogłoszeniach: "must love us both equally", "no drama", "nie możecie spotykać się osobno", "nasze zasady". Para zakłada że trzecia osoba dopasuje się do ich dynamiki, nie będzie chciała niczego "za dużo" i zniknie gdy nie będzie już potrzebna. W efekcie unicorn hunting jest krytykowane w społeczności poly jako traktowanie drugiego człowieka jak zabawki, nie partnera. Nie oznacza to że trójki nie mogą działać — mogą i działają świetnie. Różnica jest prosta: jeśli trzecia osoba ma takie same prawa i głos jak reszta, to nie jest hunting. Jeśli ma się dopasować do Waszego gotowego scenariusza — to jest.', category: 'CNM / Poliamoria', examples: ['Unicorn hunting bywa problematyczne gdy para traktuje trzecią osobę jako dodatek, nie równorzędnego partnera.'] },
  { term: 'Primary / Secondary Partner', slug: 'primary-secondary-partner', definition: 'W modelu hierarchicznym poly partnerzy mają różne "poziomy" — primary to partner główny (najczęściej mieszkacie razem, macie wspólne finanse, decydujecie razem o ważnych sprawach), secondary to partner drugorzędny, który ma mniej "przywilejów". Brzmi zimno i trochę jest. Zwolennicy mówią że to uczciwe i przejrzyste — każdy wie na czym stoi. Krytycy mówią że uprzedmiotawia secondary partnerów, sprowadzając ich do roli "drugorzędnych". W praktyce wiele osób używa tych słów żeby opisać realia swojego życia, nie żeby kogoś umniejszyć. Alternatywą jest model non-hierarchiczny gdzie nie ma formalnej hierarchii — każda relacja jest ceniona za siebie. Jeśli rozważasz hierarchical poly, warto porozmawiać z potential secondary partnerem o tym czego się spodziewać — zanim ktoś się zakoccha i odkryje że ma być "na drugim miejscu".', category: 'CNM / Poliamoria', examples: ['W hierarchical poly partner primary często ma prawo weta przy nowych relacjach.'] },
  { term: 'Nesting Partner', slug: 'nesting-partner', definition: 'Nesting partner to osoba z którą dzielisz przestrzeń życiową — mieszkacie razem, macie wspólną łazienkę, kłócicie się o zmywarkę. "Nesting" od angielskiego "nest" — gniazdo. To ważne rozróżnienie w poly, bo zamieszkanie razem nie musi oznaczać że ta relacja jest "ważniejsza" od innych. Można mieć nesting partnera i jednocześnie równie głęboką relację z kimś kto mieszka po drugiej stronie miasta. Wspólne mieszkanie to praktyczna konfiguracja, nie hierarchia emocjonalna — przynajmniej w teorii. W praktyce bycie nesting partnerem często wiąże się z większą ilością czasu razem i naturalnym "uprzywilejowaniem" logistycznym. Warto być tego świadomym i rozmawiać z innymi partnerami o tym jak to wpływa na ich poczucie miejsca w Twoim życiu.', category: 'CNM / Poliamoria', examples: ['Mieszkam z Tomkiem (nesting partner), ale mój związek z Asią jest równie ważny emocjonalnie.'] },
  { term: 'Anchor Partner', slug: 'anchor-partner', definition: 'Anchor partner to osoba która jest Twoim głównym emocjonalnym punktem odniesienia — Twoja kotwica. Niekoniecznie mieszkacie razem, niekoniecznie jesteście "primary" w formalnym sensie, ale to do tej osoby wracasz gdy coś jest trudne, z nią świętuje sukcesy i przy niej czujesz się najbardziej sobą. Termin pochodzi ze środowisk non-hierarchical poly jako alternatywa dla "primary" — mniej korporacyjna, bardziej emocjonalna. Anchor partner to nie tytuł który się nadaje, to rola którą ktoś naturalnie zajmuje w Twoim życiu. Możesz mieć więcej niż jedną taką osobę, albo żadnej — i to też jest ok w ramach solo poly. Dobrze jest powiedzieć komuś wprost że jest Twoją kotwicą — ludzie lubią wiedzieć że są ważni.', category: 'CNM / Poliamoria', examples: ['Ona jest moim anchor partner — zawsze do niej wracam po trudnych chwilach.'] },
  { term: 'Kitchen Table Poly', slug: 'kitchen-table-poly', definition: 'Kitchen table poly to styl poliamorii gdzie wszyscy partnerzy i metamourowie znają się, lubią i mogą wspólnie usiąść przy stole kuchennym na kawę i pogadać — bez niezręczności, bez napięcia. Wyobraź sobie: Ty, Twój partner, jego inna partnerka i jej mąż — i wszyscy dobrze się bawicie na wspólnym obiedzie. Nazwa jest trochę idealistyczna, ale całkiem dobrze opisuje intencję: budowanie sieci relacji gdzie wszyscy są ze sobą w jakimś kontakcie. Kitchen table poly nie oznacza że wszyscy muszą być przyjaciółmi na zawsze — chodzi o atmosferę ciepła i otwartości zamiast dyplomatycznego dystansu. Przeciwieństwem jest parallel poly gdzie każda relacja jest osobna i partnerzy nie mają ze sobą kontaktu. Który styl pasuje — to kwestia temperamentu, nie wartości. Oba są ok.', category: 'CNM / Poliamoria', examples: ['W naszej sieci praktykujemy kitchen table poly — wszyscy razem obchodzimy urodziny.'] },
  { term: 'Parallel Poly', slug: 'parallel-poly', definition: 'Parallel poly to styl poliamorii gdzie każda relacja istnieje osobno — partnerzy wiedzą o sobie nawzajem, ale nie mają bezpośredniego kontaktu. Twój partner wie że masz kogoś innego, ale nie zna tej osoby, nie spotykają się, nie ma wspólnych obiadów ani znajomości. To przeciwieństwo kitchen table poly. Dla wielu osób parallel poly jest wygodniejszy — mniej skomplikowanych dynamik grupowych, mniej potencjalnych konfliktów między partnerami. Kryteria: szanuj prywatność każdego z partnerów, nie opowiadaj jednej osobie o drugiej bez zgody, nie porównuj. Parallel poly sprawdza się szczególnie gdy partnerzy mają bardzo różne środowiska i style życia. Ważne: "parallel" nie znaczy "tajne" — wszyscy wiedzą o istnieniu innych, po prostu nie wchodzą w bezpośrednie relacje.', category: 'CNM / Poliamoria', examples: ['Ona i jej mąż preferują parallel poly — każde ma swoje osobne życie.'] },
  { term: 'Solo Poly', slug: 'solo-poly', definition: 'Solo poly to styl poliamorii gdzie osoba świadomie priorytetyzuje własną niezależność i nie szuka "głównego partnera". Każda relacja stoi sama za siebie — bez planu na wspólne mieszkanie, wspólne finanse ani wspinania się po "relationship escalator". Solo poly to nie "jestem singlem co sypia z wieloma osobami" — to świadoma filozofia dotycząca tego jak chcesz budować relacje. Taka osoba może mieć głębokie, długoterminowe związki — po prostu nie szuka kogoś kto będzie "the one". Często wybierana przez osoby które cenią własną przestrzeń, autonomię i nie chcą być zdefiniowane przez swoją relację. Może być błędnie odczytana jako "niedostępna emocjonalnie" — zazwyczaj tak nie jest. To po prostu inny model niż ten który społeczeństwo uznaje za domyślny.', category: 'CNM / Poliamoria', examples: ['Jako solo poly, nie szukam głównego partnera — cenię niezależność i każdy związek traktuję osobno.'] },
  { term: 'Hierarchical Poly', slug: 'hierarchical-poly', definition: 'Hierarchical poly to model w którym relacje są uszeregowane — partner primary ma więcej praw, czasu i priorytetów niż partnerzy secondary. Brzmi zimno, ale dla wielu jest uczciwe i przejrzyste — każdy wie na czym stoi zanim zainwestuje emocjonalnie. Hierarchia może być formalna ("mamy zasadę że partner primary ma prawo weta") albo nieformalna (po prostu tak wychodzi logistycznie bo mieszkacie razem). Krytycy wskazują że secondary partnerzy często czują się jak "opcja B" i cierpią gdy hierarchia jest używana do tłumienia ich potrzeb. Zwolennicy mówią że bez hierarchii trudno chronić istniejące zobowiązania — np. jeśli masz dzieci z partnerem primary. Klucz to transparentność na początku: jeśli ktoś wchodzi w relację wiedząc że jest secondary, mając pełną informację — to inna sytuacja niż gdy odkrywa to po fakcie.', category: 'CNM / Poliamoria', examples: ['W hierarchical poly partner primary może mieć prawo weta przy nowych relacjach.'] },
  { term: 'Non-hierarchical Poly', slug: 'non-hierarchical-poly', definition: 'Non-hierarchical poly to model bez formalnej hierarchii — każda relacja jest ceniona za siebie, nikt nie jest "ważniejszy" z góry. Nie znaczy to że wszystkie relacje są identyczne — naturalnie masz z kimś więcej wspólnego czasu, z kimś innym głębszą więź emocjonalną. Ale nie ma formalnego tytułu który daje jednej osobie "uprawnienia" do decydowania o innych Twoich relacjach. W praktyce bywa wymagające — gdy pojawiają się konflikty, nie ma prostej hierarchii która decyduje "kto ma pierwszeństwo". Wymaga więcej indywidualnych rozmów i negocjacji. Dla wielu jest jednak zdrowsze bo traktuje każdego partnera jako pełnoprawną osobę, nie jako "drugi wybór". Popularny wśród osób które mają złe doświadczenia z hierarchical poly gdzie secondary partnerzy czuli się instrumentalnie traktowani.', category: 'CNM / Poliamoria', examples: ['Preferujemy non-hierarchical poly — każdy związek ma swoją własną wartość.'] },
  { term: 'Relationship Anarchy', slug: 'relationship-anarchy', definition: 'Relationship anarchy (RA) to filozofia odrzucająca sztywne kategorie relacji w ogóle — nie tylko romantycznych. Nie ma wyraźnej granicy między "przyjacielem" a "partnerem", między "romantyczną miłością" a "głęboką przyjaźnią". Każda relacja jest definiowana na własnych warunkach przez osoby w niej uczestniczące, bez presji społecznych skryptów. Termin wymyśliła Szwedka Andie Nordgren w 2006 roku i od tej pory filozofia RA rozrosła się w silny nurt. RA idzie dalej niż polyamoria — to nie jest po prostu "mam wielu partnerów", to fundamentalne kwestionowanie tego czym w ogóle jest relacja. Dla jednych brzmi jak wolność, dla innych jak chaos. W praktyce RA wymaga bardzo dobrej komunikacji i dużej self-awareness — bo skoro nie ma gotowych zasad, wszystko trzeba budować od zera.', category: 'CNM / Poliamoria', examples: ['Relationship anarchy pozwala tworzyć relacje bez presji etykiet i oczekiwań społecznych.'] },
  { term: 'Veto Power', slug: 'veto-power', definition: 'Veto power to prawo jednego partnera do "zawetowania" innej relacji partnera — powiedzenia "nie chcę żebyś spotykał się z tą osobą" i żeby to decydowało. Gorący temat w poly community: jedni uważają veto za niezbędne narzędzie bezpieczeństwa, inni — za kontrolę i naruszenie autonomii partnera. Argument za: pozwala chronić związek primary gdy pojawiają się realne problemy (np. partner zakochuje się w kimś kto go demoralizuje). Argument przeciw: daje jednej osobie władzę nad życiem drugiej, co jest problematyczne. Większość doświadczonych osób w poly odchodzi od formalnego veto na rzecz rozmów o uczuciach i potrzebach — bo "nie możesz się z nią spotykać" to kontrola, a "czuję się niepewnie gdy widzę jak spędzacie czas" to komunikacja. To duża różnica.', category: 'CNM / Poliamoria', examples: ['Zrezygnowaliśmy z veto — wolimy rozmawiać o uczuciach niż używać uprawnień.'] },
  { term: 'Triad', slug: 'triad', definition: 'Triad to związek trzech osób gdzie każda para w grupie jest ze sobą — A kocha B, B kocha C, C kocha A. Wszyscy są ze wszystkimi, tworzą zamkniętą trójkę. To jedna z najbardziej pożądanych konfiguracji w ogłoszeniach CNM i jednocześnie jedna z najtrudniejszych do zbudowania organicznie. Dlaczego trudna? Bo wymaga chemii między trzema parami jednocześnie, kompatybilności trzech różnych charakterów i zazwyczaj mnóstwa negocjacji. Triady które "rosną naturalnie" — gdy trzy osoby zakochują się stopniowo — mają znacznie wyższy wskaźnik sukcesu niż te budowane "z góry" przez parę szukającą trzeciej osoby. To ostatnie to unicorn hunting w innym opakowaniu. Gdy triad działa — jest naprawdę piękny. Gdy nie działa — jest trzy razy więcej emocji.', category: 'CNM / Poliamoria', examples: ['Tworzą triad od trzech lat i wszystkim wychodzi świetnie.'] },
  { term: 'Quad', slug: 'quad', definition: 'Quad to związek czterech osób — zazwyczaj dwie pary gdzie wszyscy są połączeni ze sobą nawzajem. Para A spotyka parę B, zakochują się cross, i nagle masz cztery osoby w sieci wzajemnych relacji. Matematycznie: sześć możliwych par w czterech osobach — każda z tych par to osobna dynamika do zarządzania. To bardzo dużo "moving parts". Gdy działa — quady bywają bardzo stabilne bo masz wbudowany support system. Gdy nie działa — jeden konflikt może destabilizować całą sieć. Quady często zaczynają się od swapowania między parami i ewoluują w głębsze relacje emocjonalne. Wymaga kompatybilności na wielu poziomach jednocześnie: seksualnej, emocjonalnej, życiowej. Rzadkie, ale nie mityczne — istnieją szczęśliwe quady które żyją razem od lat.', category: 'CNM / Poliamoria', examples: ['Quad to cztery osoby tworzące sieć wzajemnych relacji.'] },
  { term: 'V-relationship', slug: 'v-relationship', definition: 'V-relationship to konfiguracja gdzie jedna osoba (zwana hinge) ma dwóch partnerów, którzy nie są ze sobą w relacji. Kształt jak litera V — hinge jest na wierzchołku, dwaj partnerzy na końcach ramion. To jedna z najprostszych i najczęstszych konfiguracji poly. Jeśli jesteś z Anią i z Tomkiem, a Ania i Tomek nie są ze sobą — jesteś hinge w V. Ania i Tomek są swoimi metamourami. Hinge pozycja jest wymagająca — jesteś mostem między dwiema osobami, zarządzasz dwiema relacjami, musisz dbać o to żeby żadna ze stron nie czuła się pominięta. Gdy V jest oparte na parallel poly — partnerzy w ogóle się nie spotykają. Gdy na kitchen table — siedzą razem przy herbacie. Obie opcje działają, zależnie od temperamentu wszystkich zaangażowanych.', category: 'CNM / Poliamoria', examples: ['Ty jesteś z Anią i z Tomkiem, ale Ania i Tomek nie są ze sobą — to V-relationship, Ty jesteś hinge.'] },
  { term: 'Hinge', slug: 'hinge', definition: 'Hinge (zawias) to osoba która jest w centrum V-relationship — ma dwóch (lub więcej) partnerów którzy nie są ze sobą. Słowo pochodzi od zawiasu drzwiowego który łączy dwa skrzydła. Rola hinge bywa piękna i wymagająca jednocześnie. Piękna bo masz dwie głębokie relacje naraz. Wymagająca bo musisz dbać o obie, komunikować się z obiema stronami i pilnować żeby żadna nie czuła się zaniedbana. Częsta pułapka: hinge staje się buforem emocjonalnym gdy partnerzy mają problem z metamourem — i nagle musisz mediować między dwiema osobami które nie rozmawiają ze sobą bezpośrednio. Dobra praktyka: zachęcaj partnerów do bezpośredniej komunikacji gdy to możliwe, zamiast przekazywać wszystko przez siebie. Hinge to nie tłumacz, nie dyplomata i nie terapeuta — przynajmniej nie powinien być.', category: 'CNM / Poliamoria', examples: ['Jako hinge masz odpowiedzialność wobec obojga partnerów — wymagające, ale satysfakcjonujące.'] },
  { term: 'Cowboy / Cowgirl', slug: 'cowboy-cowgirl', definition: 'Cowboy albo cowgirl to osoba która świadomie wchodzi w relację z kimś poly z zamiarem "zabrania ich ze sceny" — czyli stopniowego przekonania ich do monogamii wyłącznie z sobą. Metafora pochodzi od "wranglowania" — ujarzmienia kogoś jak dzikiego konia. Brzmi romantycznie tylko z jednej strony. Dla osoby poly często jest to zdrada zaufania — wchodzisz w relację wiedząc o ich lifestyle, a potem systematycznie podważasz go. Red flags: "czy naprawdę potrzebujesz innych?", "może jesteś poly tylko bo nie spotkałeś jeszcze właściwej osoby", naciski na rezygnację z innych relacji. Nie każda osoba mono zakochana w kimś poly to cowboy — różnica jest w intencji. Zdrowa wersja: szczera rozmowa o tym że chcesz monogamii i zostawienie drugiej osobie wyboru bez manipulacji.', category: 'CNM / Poliamoria', examples: ['Spotykasz się z kimś kto wie że jesteś poly, ale mówi "zakochasz się i zostawisz innych".'] },
  { term: 'Couple Privilege', slug: 'couple-privilege', definition: 'Couple privilege to nieuświadomiona (lub świadoma) przewaga jaką istniejąca para ma nad innymi partnerami w układzie poly. Mieszkają razem, mają wspólne finanse, decydują o ważnych sprawach razem — a inni partnerzy mają się dostosować do ich rozkładu, zasad i preferencji. Brzmi znajomo? Bo to trochę jak biały przywilej ale w relacjach. Para nie zawsze zdaje sobie sprawę że to robi. Objawy: "nasze zasady", "my zdecydujemy czy możesz się z nimi spotykać", "masz się dopasować do naszego harmonogramu". Nie chodzi o to że para nie może mieć wspólnych ustaleń — chodzi o to gdy te ustalenia jednostronnie ograniczają autonomię innych partnerów bez uwzględnienia ich potrzeb. Remedium: regularne pytanie "jak to wygląda z Twojej perspektywy?" skierowane do wszystkich stron.', category: 'CNM / Poliamoria', examples: ['Couple privilege pojawia się gdy para traktuje swój związek jako ważniejszy od wszystkich innych.'] },
  { term: 'Relationship Escalator', slug: 'relationship-escalator', definition: 'Relationship escalator to metafora ruchomych schodów — społeczny skrypt który mówi jak "powinien" wyglądać związek: randkowanie → wyłączność → zamieszkanie → zaręczyny → ślub → dzieci → koniec. Każdy krok prowadzi do następnego, zatrzymanie się jest podejrzane, cofnięcie się to "problem". W CNM i poly wiele osób świadomie z tych schodów schodzi — bo może chcesz głębokiej relacji bez zamieszkiwania razem, albo chcesz mieszkać razem bez ślubu, albo chcesz w ogóle definiować to co macie po swojemu. "Stepping off the escalator" to popularny termin na świadome odejście od tego skryptu. Warto wiedzieć że escalator nie jest złem wcielonym — dla wielu jest świetny. Problem pojawia się gdy traktujesz go jako jedyną możliwą drogę i oceniasz innych przez jego pryzmat.', category: 'CNM / Poliamoria', examples: ['W CNM związek może być głęboki i wartościowy bez "wspinania się" po schodach ruchomych.'] },
  { term: 'OPP (One Penis Policy)', slug: 'one-penis-policy', definition: 'OPP to zasada w parze hetero gdzie mężczyzna "pozwala" partnerce spotykać się z kobietami, ale nie z innymi mężczyznami. On może albo nie może spotykać się z innymi — zależy od konkretnej pary. Powszechnie krytykowana w środowisku CNM z kilku powodów naraz. Po pierwsze: traktuje partnerkę jak własność ("pozwalam ci"). Po drugie: deprecjonuje jej relacje z kobietami jako mniej poważne lub niezagrażające. Po trzecie: zazwyczaj wynika z insecurity mężczyzny a nie z przemyślanego modelu. Po czwarte: jest seksistowska bo zakłada że kobiety są "bezpieczne" a mężczyźni — zagrożeniem. Jeśli naprawdę chcesz otwartego związku, warto zadać sobie pytanie: skąd pochodzi ten strach i czy da się przepracować go inaczej niż przez zasadę?', category: 'CNM / Poliamoria', examples: ['OPP jest krytykowana za to że traktuje partnerkę jak własność i deprecjonuje jej relacje z kobietami.'] },
  { term: 'DADT (Don\'t Ask, Don\'t Tell)', slug: 'dadt', definition: 'DADT to typ otwartego związku gdzie partnerzy mogą mieć seks z innymi osobami, ale nie mówią sobie o tym — ani nie pytają. "Co się dzieje poza nami, zostaje poza nami." Nazwa pochodzi od kontrowersyjnej polityki US Army wobec homoseksualnych żołnierzy — tutaj używana bez tego kontekstu, czysto opisowo. Dla niektórych par DADT działa świetnie: chcą wolności ale nie chcą szczegółów które wywołują zazdrość lub dyskomfort. Dla innych jest to forma zaprzeczenia — udajemy że to się nie dzieje, choć oboje wiemy że się dzieje. Krytycy mówią że DADT uniemożliwia prawdziwą rozmowę o granicach, testach na STI i emocjach. Zwolennicy mówią że to świadomy wybór pary i każdy ma prawo do swojego modelu. Jak zawsze: jeśli oboje zgadzacie się w pełni świadomie — Wasza sprawa.', category: 'CNM / Poliamoria', examples: ['DADT działa dla niektórych par, ale bywa krytykowane za brak transparency.'] },
  { term: 'Fluid Bonding', slug: 'fluid-bonding', definition: 'Fluid bonding to świadoma decyzja o uprawianiu seksu bez prezerwatyw z konkretnym partnerem — zazwyczaj po wzajemnych testach na STI i po ustaleniu co robią z innymi partnerami. "Fluid" odnosi się do płynów ustrojowych. To nie jest tylko kwestia wygody czy przyjemności — to akt zaufania i intymności, szczególnie w środowisku CNM gdzie masz kilku partnerów. Warunki dobrego fluid bondingu: oboje zrobiliście testy, znacie wyniki, ustaliliście jakich zasad przestrzegacie z innymi partnerami (np. zawsze kondom z nowymi osobami), regularnie powtarzacie testy. Fluid bonding z jedną osobą to zobowiązanie które wpływa na wszystkich innych Twoich partnerów — dlatego warto omówić to ze wszystkimi zainteresowanymi, nie tylko z daną osobą. To jeden z tych tematów gdzie transparentność dosłownie chroni zdrowie.', category: 'CNM / Poliamoria', examples: ['Fluid bonding wymaga wzajemnego zaufania i regularnych testów — nie robi się tego z nową osobą.'] },
  { term: 'Poly-Saturated', slug: 'poly-saturated', definition: 'Poly-saturated to stan w którym masz już tyle relacji ile jesteś w stanie zdrowo podtrzymywać — emocjonalnie, czasowo, energetycznie. Jesteś "pełny". Nie ma już miejsca na nową relację bez zaniedbania istniejących. Termin jest całkowicie neutralny — to nie jest wada ani cnota, to po prostu obserwacja swoich możliwości. Każdy ma inną pojemność: niektórzy czują się poly-saturated przy dwóch partnerach, inni przy pięciu. Zależy od intensywności relacji, Twojego temperamentu, sytuacji życiowej i ile czasu masz po pracy i śnie. Ważna umiejętność: rozpoznać że jesteś poly-saturated ZANIM zaczniesz nową relację i zawieść kogoś kto na Ciebie liczył. Mówienie "nie mam teraz miejsca na nową relację" to uczciwe i dojrzałe — nie każdy musi wieczne szukać nowych połączeń.', category: 'CNM / Poliamoria', examples: ['Jestem teraz poly-saturated — trzy relacje to moje maksimum.'] },
  { term: 'Mononormatywność', slug: 'mononormatywnosc', definition: 'Mononormatywność to założenie wbudowane w kulturę że monogamia jest domyślna, naturalna i jedyna właściwa forma związku — a wszystko inne jest dziwne, niezdrowe lub przejściowe. Przejawia się w pytaniach typu "kiedy się w końcu ustatkujesz?", "nie boisz się że Cię zdradzi?", "ale kogo tak naprawdę bardziej kochasz?" albo w tym że formularze mają pole tylko na jednego partnera/małżonka. Mononormatywność nie jest złośliwa — większość ludzi po prostu powtarza to czego się nauczyli. Ale dla osób w CNM czy poly bywa wyczerpująca: ciągłe tłumaczenie, ukrywanie, lub zderzanie się z niezrozumieniem. Świadomość mononormatywności nie oznacza że musisz nawracać każdego monogamisty — monogamia jest ok. Chodzi o to żeby żaden model nie był traktowany jako jedyny możliwy.', category: 'CNM / Poliamoria', examples: ['"Kiedy się w końcu ustatkujesz?", "Takie związki się nie udają" — przykłady mononormatywnych komentarzy.'] },
  { term: 'Monogamish', slug: 'monogamish', definition: 'Monogamish to związek który jest w zasadzie monogamiczny ale z ustalonymi wyjątkami — para jest razem, jest ich "głównym" układem, ale od czasu do czasu, na ustalonych zasadach, mogą mieć doświadczenia z innymi. Termin wymyślił Dan Savage, seksuolog i publicysta, opisując swój własny związek. Monogamish jest gdzieś na continuum między monogamią a otwartym związkiem — bliżej monogamii. Wyjątki mogą być rzadkie (raz w roku na urlopie) lub częstsze, seksualne bez emocji, mogą angażować oboje partnerów naraz lub osobno. Kluczowe: "ish" — "prawie". To nie jest otwarta poliamoria, to nie jest full swinging, to po prostu mała elastyczność w ramach silnego, stabilnego związku. Dla wielu par to idealne rozwiązanie które pozwala mieć i ciągłość, i odrobinę przygody.', category: 'CNM / Poliamoria', examples: ['Jesteśmy monogamish — czasem mamy przygody, ale zawsze razem o tym decydujemy.'] },
  { term: 'De-escalate', slug: 'de-escalate', definition: 'De-escalate to świadome zmniejszenie intensywności lub zakresu relacji — bez jej kończenia. Przykłady: przestajecie mieszkać razem ale dalej jesteście parą, rezygnujecie z planów wspólnej przyszłości ale zostajecie ważnymi osobami w swoim życiu, ograniczacie częstotliwość spotkań. To przeciwieństwo "relationship escalator" — zamiast ciągłego "wchodzenia wyżej", czasem lepiej jest zejść o poziom. De-escalation bywa odbierana jako "porażka" lub "rozpad związku" — szczególnie przez osoby z zewnątrz. W rzeczywistości często ratuje relację i czyni ją zdrowszą. Para która ze wspólnego mieszkania wraca do osobnych, ale spotyka się regularnie i jest szczęśliwa — to sukces, nie porażka. W CNM de-escalation jest narzędziem, nie klęską.', category: 'CNM / Poliamoria', examples: ['Zdecydowaliśmy się de-escalować — teraz mieszkamy osobno, ale relacja jest zdrowsza.'] },
  { term: 'Check-in', slug: 'check-in', definition: 'Check-in to regularna, zaplanowana rozmowa z partnerem o stanie waszej relacji — jak się czujecie, czy są jakieś niezaspokojone potrzeby, co działa dobrze a co można poprawić. W CNM check-iny są szczególnie ważne bo masz więcej "moving parts" — więcej osób, więcej emocji, więcej potencjalnych nieporozumień. Dobry check-in to nie kłótnia i nie przesłuchanie — to bezpieczna przestrzeń na powiedzenie "ostatnio czuję się trochę pominięta" albo "chciałbym żebyśmy spędzali więcej czasu sami". Częstotliwość: co tydzień lub co dwa tygodnie to dobry rytm dla par w aktywnym CNM. Format: możecie mieć konkretne pytania które zawsze zadajecie sobie nawzajem ("jak się czujesz na skali 1-10?", "czy jest coś o czym chciałeś porozmawiać?"). Check-in to nawyk który oszczędza wiele małych i dużych kryzysów zanim te w ogóle wybuchną.', category: 'CNM / Poliamoria', examples: ['Co tydzień mamy check-in — 30 minut tylko na rozmowę o nas.'] },
  { term: 'FWB (Friends with Benefits)', slug: 'fwb', definition: 'FWB, czyli przyjaciele z korzyściami, to relacja między ludźmi którzy się lubią, przyjaźnią, ale też uprawiają ze sobą seks — bez romantycznego zaangażowania i bez etykiety "para". "No strings attached" — bez zobowiązań. W kontekście CNM FWB to jedna z wielu możliwych konfiguracji: masz głównych partnerów i kilka FWB z którymi spotykasz się okazjonalnie. Brzmi prosto, w praktyce bywa skomplikowane: jedno z was może z czasem chcieć czegoś więcej, albo odwrotnie — jeden z was chce zakończyć seksualny aspekt ale zachować przyjaźń. Klucz do zdrowego FWB: rozmowa o oczekiwaniach na początku i regularne upewnianie się że oboje nadal chcecie tego co macie. "No strings" nie znaczy "zero komunikacji" — znaczy "brak romantycznych zobowiązań".', category: 'CNM / Poliamoria', examples: ['Mamy FWB — lubimy się, spędzamy czas, ale żadne z nas nie chce "czegoś więcej".'] },
  { term: 'Comet', slug: 'comet', definition: 'Comet to partner z którym spotykasz się rzadko — może kilka razy w roku, może przy okazji podróży albo konferencji — ale relacja jest intensywna i wartościowa mimo rzadkości kontaktu. Jak kometa: pojawia się nieregularnie, ale gdy jest — jest jasna i wyraźna. Comet relationships są szczególnie popularne wśród osób które dużo podróżują lub mają rozproszonych geograficznie znajomych w środowisku lifestyle. Nie ma tu presji codziennego kontaktu ani regularnych randek — relacja żyje własnym rytmem. Może być seksualna, romantyczna, albo jedno i drugie. Wymaga akceptacji że ta osoba nie będzie "dostępna" na co dzień — i że to jest ok. Dla niektórych comet jest idealną formą bo daje intensywność bez logistyki długoterminowej relacji.', category: 'CNM / Poliamoria', examples: ['On jest moim comet — widzimy się 3-4 razy w roku, ale to ważna relacja.'] },
  { term: 'Ethical Slut', slug: 'ethical-slut', definition: '"The Ethical Slut" to tytuł kultowej książki Dossie Easton i Janet Hardy z 1997 roku — i zarazem termin który autorki świadomie "odzyskały" ze słownika obraźliwego. Ethical slut to osoba świadomie i etycznie aktywna seksualnie z wieloma partnerami — ktoś kto lubi seks, ma wielu partnerów, i robi to w sposób uczciwy, z szacunkiem i za zgodą wszystkich zaangażowanych. "Slut" (suka, puszczalska) w tym kontekście jest użyte z dumą i humorem — jako odpowiedź na kulturę która stygmatyzuje seksualną aktywność, szczególnie kobiet. Książka to lektura obowiązkowa dla każdego zaczynającego przygodę z CNM — nie tylko dlatego że definiuje pojęcia, ale dlatego że ma ciepły, nieoceniający, praktyczny głos. Jeśli czytasz jeden rozdział — przeczytaj ten o zazdrości.', category: 'CNM / Poliamoria', examples: ['"The Ethical Slut" to lektura obowiązkowa dla każdego zaczynającego w CNM.'] },

  // === SWINGING / LIFESTYLE ===
  { term: 'Swinging', slug: 'swinging', definition: 'Swinging to styl życia w którym pary — najczęściej heteroseksualne, choć nie wyłącznie — konsensualnie wymieniają się partnerami seksualnymi lub uczestniczą razem w grupowych aktywnościach seksualnych. Kluczowa różnica wobec poliamории: swinging koncentruje się na seksie, nie na budowaniu głębokich więzi emocjonalnych z innymi osobami. Para pozostaje parą, seks z innymi to wspólna przygoda, nie zagrożenie. Swinging ma długą historię — jego złoty wiek to lata 70. w USA, ale praktykowany był znacznie wcześniej. W Polsce scena jest aktywna i dyskretna — lifestyle cluby działają w Warszawie, Krakowie, Łodzi, Poznaniu i innych miastach. Motywacje par są różne: ciekawość, odświeżenie pożycia, wspólna przygoda, voyeuryzm, ekshibicjonizm. Najważniejsza zasada: oboje muszą chcieć — jeśli jedno z was jest "przekonywane", to zły znak.', category: 'Swinging / Lifestyle', examples: ['Para od lat praktykuje swinging w zamkniętym kręgu zaufanych przyjaciół.'] },
  { term: 'The Lifestyle', slug: 'the-lifestyle', definition: '"The Lifestyle" to tak swinging community mówi o sobie i swojej scenie — dyskretnie, bez wprost nazywania tego swingingiem. "Czy jesteście w lifestyle?" to pytanie które usłyszysz na imprezie lub portalu i które znaczy dokładnie tyle ile myślisz. Termin parasolowy dla całego środowiska: par, singli, klubów, eventów, forów. Ma w sobie coś eleganckiego — nie "sex party", nie "orgia", po prostu "lifestyle". Używany głównie w kontekście angielskim, ale w Polsce coraz powszechniejszy. Jeśli ktoś pyta czy jesteś "w lifestyle" — upewnij się że oboje partnerzy są świadomi pytania i odpowiadacie razem.', category: 'Swinging / Lifestyle', examples: ['"Jesteśmy w lifestyle od 3 lat" — czyli od 3 lat aktywnie uczestniczą w swinger scene.'] },
  { term: 'Soft Swap', slug: 'soft-swap', definition: 'Soft swap to wymiana partnerów z ograniczonym kontaktem seksualnym — całowanie, dotykanie, oral sex są ok, ale penetracja — nie. Idealne dla par które dopiero zaczynają eksplorować swinging i chcą poczuć jak to jest, zanim zdecydują się na więcej. Ale też dla par które po prostu mają taką granicę na stałe i im tak odpowiada — i to jest w pełni ok. Soft swap pozwala doświadczyć bliskości z inną osobą przy zachowaniu pewnego "ostatniego progu" tylko dla siebie nawzajem. Wiele par pozostaje na poziomie soft swap przez lata i jest z tego zadowolona. Ważne: soft swap z jedną parą nie zobowiązuje Cię do niczego z kolejną — każda interakcja jest osobną decyzją.', category: 'Swinging / Lifestyle', examples: ['Zaczęliśmy od soft swap żeby poczuć jak to jest, zanim zdecydujemy się na więcej.'] },
  { term: 'Full Swap', slug: 'full-swap', definition: 'Full swap to pełna wymiana partnerów — wszystkie aktywności seksualne włącznie z penetracją są ok. Dla wielu par to naturalna ewolucja po soft swappingu, dla innych punkt startowy. Full swap wymaga wyższego poziomu zaufania i komunikacji w parze — przed, w trakcie i po. Przed: upewnijcie się że oboje naprawdę tego chcecie, nie tylko że jedno jest "ok" z tym żeby zadowolić drugie. W trakcie: sprawdzajcie się nawzajem, szczególnie na początku. Po: porozmawiajcie o tym jak się czujecie — zarówno jeśli było super, jak i jeśli pojawiły się nieprzewidziane emocje. Full swap może być świetnym doświadczeniem; może też ujawnić uczucia na które nie byliście gotowi. Obie opcje są do zarządzenia jeśli macie dobry kontakt.', category: 'Swinging / Lifestyle', examples: ['Para zdecydowała się na full swap po roku soft swappingu.'] },
  { term: 'Same Room', slug: 'same-room', definition: 'Same room to swap gdzie wszystkie pary pozostają w tym samym pokoju i widzą się nawzajem podczas zabawy. Dla wielu par to preferowana opcja szczególnie na początku — możesz mieć kontakt wzrokowy z partnerem, czuć jego obecność, widzieć że wszystko jest ok. Same room daje poczucie wspólnoty i wspólnej przygody zamiast "każdy osobno gdzieś". Voyeurystyczny aspekt patrzenia na partnera z kimś innym bywa dla wielu silnie podniecający. Same room nie znaczy że musisz cały czas patrzeć — po prostu wszyscy są w tej samej przestrzeni. Dla newbies same room jest zazwyczaj bezpieczniejszym punktem startowym niż separate room.', category: 'Swinging / Lifestyle', examples: ['Same room pozwala pozostać w kontakcie wzrokowym z partnerem podczas zabawy.'] },
  { term: 'Separate Room', slug: 'separate-room', definition: 'Separate room to opcja gdzie pary idą do osobnych pokoi — nie widzisz co Twój partner robi i on nie widzi Ciebie. Pełna prywatność z drugą parą. Wymaga znacznie wyższego poziomu zaufania i komfortu — nie ma wzrokowego "sprawdzania" partnera, musisz być ok z tym że nie wiesz dokładnie co się dzieje. Dla doświadczonych par separate room bywa bardziej intensywnym i swobodniejszym doświadczeniem — możesz w pełni skupić się na drugiej osobie bez myślenia o tym co widzi partner. Jeśli rozważasz separate room po raz pierwszy — porozmawiajcie wcześniej o tym jak się będziecie czuć i ustalcie co się dzieje po — np. spotykacie się w barze po godzinie.', category: 'Swinging / Lifestyle', examples: ['Po roku w lifestyle zdecydowali się na separate room — wzajemne zaufanie jest na to gotowe.'] },
  { term: 'Hotka / Hotwife', slug: 'hotka', definition: 'Hotka (po angielsku hotwife) to żona lub stała partnerka która uprawia seks z innymi mężczyznami — i czasem kobietami — za pełną wiedzą i zgodą swojego partnera. Kluczowy element: focus na przyjemności i seksualnej wolności kobiety, z mężem jako aktywnym, dumnym uczestnikiem tej dynamiki — nawet jeśli sam nie śpi z innymi. Hotka różni się od zwykłego otwartego związku przede wszystkim klimatem: to nie "oboje możemy" ale "ona może i oboje to celebrujemy". Mąż czerpie podniecenie z sukcesu seksualnego żony, jej atrakcyjności dla innych mężczyzn, z opowieści lub obserwowania. Hotkowanie wymaga bardzo dobrej komunikacji i pewności siebie po obu stronach. Nie jest synonimem rogacza — hotka jest pozbawiona elementu upokorzenia, to celebracja, nie poniżenie.', category: 'Swinging / Lifestyle', examples: ['W hotkowanie chodzi o wolność i spełnienie kobiety — mąż z dumą i podnieceniem wspiera jej przygody.'] },
  { term: 'Rogacz / Cuckold', slug: 'cuckolding', definition: 'Rogacz (po angielsku cuckold) to mąż lub partner który czerpie podniecenie z tego że jego żona uprawia seks z innym mężczyzną — zwanym byczkiem lub bullem. W odróżnieniu od hotkowania, dynamika rogacza często zawiera element psychologicznego upokorzenia: byczek jest przedstawiany jako "lepszy", silniejszy, bardziej atrakcyjny, a mąż jako "niewystarczający". To świadoma, negocjowana gra erotyczna — nie rzeczywiste upokorzenie wbrew woli. Rogacz może być obecny i obserwować, słyszeć o tym po fakcie, albo być aktywnie wykluczany jako część fantazji. Cuckolding jest jedną z najpopularniejszych fantazji seksualnych wśród mężczyzn i istnieje od wieków. W Polsce Lava Club organizuje regularne imprezy pod szyldem "Rogacz i Hotka" — oba terminy funkcjonują równolegle.', category: 'Swinging / Lifestyle', examples: ['Rogacz to świadoma gra z dominacją i uległością — kluczowa jest zgoda i negocjacja.'] },
  { term: 'Byczek / Bull', slug: 'bull', definition: 'Byczek (po angielsku bull) to mężczyzna który uprawia seks z hotką lub partnerką rogacza. Stereotypowo bywa opisywany jako pewny siebie, dominujący, fizycznie imponujący — ale to przede wszystkim rola w fantazji, nie wymóg rekrutacyjny. W praktyce byczek to po prostu mężczyzna który wszedł w tę dynamikę ze świadomością swojej roli. Byczek zazwyczaj ma relację seksualną z kobietą, rzadziej bezpośredni kontakt z jej partnerem — choć w zależności od pary układy bywają różne. Dobry byczek rozumie że wchodzi w czyjś związek i zachowuje się z szacunkiem wobec obojga partnerów, nie tylko tej z którą śpi. Bycie byczkiem to odpowiedzialność — nie tylko przywilej.', category: 'Swinging / Lifestyle', examples: ['Byczek w hotkowanie jest partnerem hotki — zazwyczaj nie ma relacji z mężem.'] },
  { term: 'Stag / Vixen', slug: 'stag-vixen', definition: 'Stag/vixen to dynamika podobna do hotwife/cuckolding, ale z jedną kluczową różnicą: brak elementu upokorzenia. Stag (jeleń) to partner który z dumą i podnieceniem obserwuje lub wie o przygodach vixen (lisicy) — bez żadnej narracji o byciu "niewystarczającym". Vixen cieszy się wolnością seksualną, stag cieszy się jej sukcesem i seksualnością. To czysta celebracja, nie gra ze wstydem. Dla par które przyciąga hotwifing ale odpycha humiliation dynamic — stag/vixen jest naturalnym wyborem. Stag może być aktywnie zaangażowany (obserwuje, rozmawia z bullem, planuje z żoną) albo bardziej z dystansu — każda para definiuje swoje granice. Zdrowa dynamika stag/vixen opiera się na wzajemnym szacunku i entuzjazmie obojga.', category: 'Swinging / Lifestyle', examples: ['Stag/vixen to dla par które chcą seksualnej wolności bez humiliation dynamics.'] },
  { term: 'MFM / MMF', slug: 'mfm-mmf', definition: 'Obydwa skróty oznaczają threesome z kobietą i dwoma mężczyznami — ale jest ważna różnica. MFM (Male-Female-Male): obaj mężczyźni skupiają się na kobiecie, nie ma między nimi kontaktu fizycznego. MMF (Male-Male-Female): mężczyźni też mają kontakt ze sobą — to wariant bi lub bi-curious. Dla większości par swingujących MFM to standardowy układ w którym mężczyźni są straight. MMF jest rzadszy i wymaga wyraźnego ustalenia że wszyscy są ok z kontaktem M-M. Wiele profili na portalach lifestyle wyraźnie pisze "MFM only" albo "MMF welcome" właśnie żeby uniknąć nieporozumień. Jeśli nie wiesz — zapytaj zanim zaproponujesz spotkanie.', category: 'Swinging / Lifestyle', examples: ['Para szuka partnera do MFM — obu mężczyzn interesuje wyłącznie kobieta.'] },
  { term: 'FMF / FFM', slug: 'fmf-ffm', definition: 'Threesome z mężczyzną i dwiema kobietami — i tu też litery mają znaczenie. FMF (Female-Male-Female): kobiety skupiają się na mężczyźnie, brak kontaktu F-F. FFM (Female-Female-Male): kobiety też bawią się ze sobą — wariant bi lub bi-curious. FMF to fantasy #1 heteroseksualnych mężczyzn od zarania dziejów — każdy chce, niewielu jest na to gotowych emocjonalnie jako para. FFM jest bardziej rozpowszechniony w swinging bo wiele kobiet odkrywa lub potwierdza biseksualność w bezpiecznym kontekście lifestyle. Partnerki nie muszą mieć doświadczeń bi przed pierwszym FFM — to często naturalna ewolucja. Ważne: obydwie kobiety muszą chcieć, nie jedna dla przyjemności drugiej.', category: 'Swinging / Lifestyle', examples: ['Para szuka kobiety do FFM — obydwie kobiety są bi.'] },
  { term: 'Gang Bang', slug: 'gang-bang', definition: 'Gang bang to sytuacja w której jedna osoba — najczęściej kobieta — uprawia seks z wieloma partnerami (zazwyczaj mężczyznami) jednocześnie lub po kolei. W kontekście lifestyle to świadoma, planowana i chciana przez wszystkie strony aktywność. Osoby które biorą udział od strony "centrum" często opisują to jako intensywne, przytłaczające w pozytywnym sensie doświadczenie skupienia całej uwagi na sobie. W lifestyle clubs gang bangi bywają organizowane jako tematyczne eventy lub private sesje. Zawsze wymagają wcześniejszego ustalenia zasad: kto, ile osób, jakie aktywności, bezpieczeństwo. Słowo brzmi hardcorowo — ale w praktyce to zorganizowane doświadczenie z konsensualnymi uczestnikami.', category: 'Swinging / Lifestyle', examples: ['Gang bang to jeden z typowych tematycznych eventów w klubach swingerskich.'] },
  { term: 'Reverse Gang Bang', slug: 'reverse-gang-bang', definition: 'Reverse gang bang to odwrócona wersja klasycznego gang bangu: jeden mężczyzna uprawia seks z wieloma kobietami — jednocześnie lub po kolei. Rzadszy niż klasyczny, ale popularny jako fantasy i realnie organizowany na specjalnych imprezach. Nazwa "reverse" pochodzi stąd że historycznie gang bang był zawsze jeden-do-wielu z kobietą w centrum. Dziś termin obejmuje też konfiguracje z osobami niebinarnymi i inne układy — ale reverse gang bang najczęściej oznacza właśnie jeden M z wieloma F. Wymaga takiego samego przygotowania jak klasyczny: zasady, bezpieczeństwo, wyrażona zgoda każdej uczestniczki.', category: 'Swinging / Lifestyle', examples: ['Reverse gang bang pojawia się rzadziej, ale jest organizowany na specjalnych imprezach.'] },
  { term: 'Train', slug: 'train', definition: 'Train (kolejka) to aktywność gdzie jedna osoba uprawia seks z wieloma partnerami — ale kolejno, nie jednocześnie. Każda osoba "wsiada do pociągu" po kolei. Różnica wobec gang bangu: tam wiele osób naraz, tu sekwencyjnie. Train bywa spontaniczną odpowiedzią na dynamikę imprezową albo planowanym doświadczeniem. Może dotyczyć kobiety lub mężczyzny w centrum. W lifestyle clubs train pojawia się w playrooms gdzie spontanicznie dołączają kolejne osoby — z zachowaniem zasady że każda nowa osoba pyta przed dołączeniem. Zasada "zapytaj zanim dołączysz" jest kluczowa i odróżnia lifestyle culture od czegokolwiek niekonsensualnego.', category: 'Swinging / Lifestyle', examples: ['Train różni się od orgy — tutaj chodzi o kolejność, nie o jednoczesność.'] },
  { term: 'Orgy / Group Play', slug: 'orgy', definition: 'Orgia, czyli group play, to seks z wieloma osobami jednocześnie — zazwyczaj 5 lub więcej. W kontekście lifestyle to zorganizowane lub spontaniczne doświadczenie grupowe, zazwyczaj w specjalnym playroom w klubie lub na prywatnej imprezie. Orgie w lifestyle mają swoje zasady: bez presji (możesz patrzeć i nie uczestniczyć), wszystko za zgodą, każdy może powiedzieć stop. Atmosfera dobrej orgii to kombinacja zabawy, swobody i wzajemnego szacunku — bardziej taniec niż chaos. Orgia bywa punktem kulminacyjnym imprezowego wieczoru albo zaplanowanym eventem tematycznym. Jeśli nigdy nie byłeś — pierwsze razy warto zacząć od obserwowania zanim zdecydujesz się dołączyć.', category: 'Swinging / Lifestyle', examples: ['Orgy w lifestyle clubie odbywa się w specjalnie wyposażonych salach.'] },
  { term: 'Voyeur', slug: 'voyeur', definition: 'Voyeur to osoba która czerpie podniecenie z patrzenia jak inni uprawiają seks — bez uczestniczenia. To jedna z najpowszechniejszych form seksualizmu, obecna w kulturze od zawsze. W kontekście lifestyle voyeuryzm jest w pełni akceptowaną praktyką — wiele klubów ma specjalne voyeur rooms gdzie możesz siedzieć, obserwować i nie robić nic więcej. Dobre lifestyle clubs jasno komunikują: kto jest w voyeur zone, wie że jest oglądany — nie ma tu podglądania bez wiedzy. Jeśli chcesz oglądać: szanuj dystans, nie wchodź w kadr jeśli nie jesteś zaproszony, nie komentuj głośno. Voyeuryzm i exhibicjonizm naturalnie się uzupełniają — jedni lubią patrzeć, drudzy lubią być widziani.', category: 'Swinging / Lifestyle', examples: ['Wiele lifestyle clubs ma specjalne voyeur rooms — możesz patrzeć, ale nie dołączać.'] },
  { term: 'Exhibicjonista', slug: 'exhibicjonista', definition: 'Exhibicjonista to osoba która czerpie podniecenie z bycia obserwowaną podczas seksu lub nagości. Odwrotność voyeura — tam podniecenie ze patrzenia, tu z bycia widzianym. W lifestyle context to w pełni akceptowana i popularna preferencja — open playrooms i voyeur zones istnieją właśnie dlatego żeby exhibicjoniści mogli się bawić z publicznością. Jeśli jesteś exhibicjonistą wchodzącym w lifestyle: open playroom jest dla Ciebie, closed room — nie. Dla par gdzie jedno jest bardziej exhibicjonistyczne niż drugie warto ustalić komfort z byciem oglądanym — nie każdy partner czuje się równie swobodnie. I nie musisz mieć perfekcyjnego ciała żeby być exhibicjonistą — ta preferencja nie ma nic wspólnego z wyglądem.', category: 'Swinging / Lifestyle', examples: ['W lifestyle clubs exhibicjoniści mogą bawić się w open playrooms.'] },
  { term: 'Hall Pass', slug: 'hall-pass', definition: 'Hall pass to "przepustka" którą jeden partner daje drugiemu na seks z kimś innym — solo, bez obecności partnera. W odróżnieniu od typowego swingu gdzie para bawi się razem, hall pass daje wolność do samodzielnej randki. Bywa jednorazowy ("masz weekend w Berlinie, korzystaj") albo regularną praktyką w bardziej otwartym związku. Hall pass wymaga jeszcze więcej zaufania niż typowy swinging — nie masz kontroli wizualnej, nie wiesz co się dokładnie dzieje. Para musi mieć bardzo szczerą rozmowę o granicach: czy możesz nocować? Czy opowiadasz po fakcie szczegóły? Czy to konkretna osoba czy ktokolwiek? Im więcej ustalone wcześniej, tym mniej komplikacji po.', category: 'Swinging / Lifestyle', examples: ['"Mam hall pass na ten weekend" — mogę się spotkać z kimś solo.'] },
  { term: 'Playroom', slug: 'playroom', definition: 'Playroom to pokój w lifestyle club lub na prywatnej imprezie wyposażony do seksu — materace, podkłady higieniczne, chusteczki, często ozdobne oświetlenie. Playroomy bywają różne: public (otwarty, widoczny dla przechodniów), semi-private (zasłona, ale można zajrzeć), private (zamknięty na klucz). W dobrym klubie publiczne playroomy mają jasne zasady: możesz patrzeć, ale nie dotykać bez zaproszenia; wchodzisz tylko jeśli jesteś zaproszony. Playroom nie jest twój — używasz go, sprzątasz po sobie, nie zostajesz w nieskończoność. Etykieta: pukaj do zamkniętych drzwi, akceptuj odmowę bez komentarza. Dobry playroom to przestrzeń bez presji — możesz wejść, poczuć atmosferę i wyjść jeśli nie jest to dla Ciebie.', category: 'Swinging / Lifestyle', examples: ['Public playroom pozwala innym patrzeć, private daje pełną prywatność.'] },
  { term: 'Dress Code', slug: 'dress-code', definition: 'Dress code w lifestyle clubs to ważna zasada — i nie chodzi tylko o estetykę. Zazwyczaj: mężczyźni — eleganckie spodnie i koszula, bez trampek i dżinsów; kobiety — sukienka, bielizna, obcasy lub strój kąpielowy. Wiele klubów ma dwufazowy dress code: do północy seksowna elegancja, po północy przejście na "towels only" lub lingerie. Dress code istnieje z kilku powodów: buduje atmosferę, odsiewa przypadkowych gapiów i tworzy poczucie wyjątkowości miejsca. Nie wiesz co założyć? Napisz do klubu — chętnie doradzą. Jeśli nie wpuszczą Cię przez dress code: to nie osobista zniewaga, po prostu zasada obowiązująca wszystkich. Przygotuj się następnym razem.', category: 'Swinging / Lifestyle', examples: ['Dress code w lifestyle klubach jest zazwyczaj seksowny ale elegancki — nie przychodzi się w dżinsach i t-shircie.'] },
  { term: 'Newbies', slug: 'newbies', definition: 'Newbies to pary lub osoby które dopiero zaczynają swoją przygodę z lifestyle. Termin używany z ciepłem, nie jako etykieta — każdy kiedyś był newbie. Typowy newbie: dużo pytań, trochę nerwów, niepewność co do etykiety, ciekawość miesza się z lękiem. To normalny stan na początku. Dobra lifestyle community wita newbies przyjaźnie i cierpliwie odpowiada na pytania. Dla newbies zalecana droga: najpierw Meet & Greet lub klub off-premise gdzie możecie poczuć atmosferę bez presji. Potem może on-premise jako obserwatorzy. Potem stopniowe wejście w zabawę. Nie musicie od razu skakać na głębinę — lifestyle najlepiej smakuje odkrywany powoli.', category: 'Swinging / Lifestyle', examples: ['Jako newbies zaczęliśmy od Meet & Greet zanim zdecydowaliśmy się na wizytę w klubie.'] },
  { term: 'Discretion', slug: 'discretion', definition: 'Discretion (dyskrecja) to jeden z fundamentalnych kodeksów lifestyle community. Oznacza: zachowanie swojego uczestnictwa w lifestyle w tajemnicy przed "vanilla" życiem — pracą, rodziną, znajomymi spoza sceny. Zasady dyskrecji są w zasadzie wszędzie takie same: nie robisz zdjęć bez wyraźnej zgody każdej osoby na zdjęciu, nie ujawniasz imion ani danych osobowych nikogo bez ich zgody, nie opowiadasz znajomym "o tym co widziałeś w klubie", nie łączysz profili lifestyle z prawdziwą tożsamością. "Co się dzieje w klubie, zostaje w klubie" to nie slogan — to realna umowa społeczna która chroni wszystkich uczestników. Naruszenie dyskrecji to poważne wykroczenie które może skutkować trwałym wykluczeniem ze społeczności.', category: 'Swinging / Lifestyle', examples: ['Discretion to podstawa — wiele osób nie chce być "outed" w swoim środowisku zawodowym.'] },
  { term: 'Verify / Weryfikacja', slug: 'weryfikacja', definition: 'Weryfikacja to potwierdzenie że profil na portalu lifestyle (lub osoba z którą chcesz się spotkać) jest prawdziwy — czyli że za profilem stoi kto twierdzi że stoi. Typowe metody: krótki video call, wymiana zdjęć z kartką z datą, spotkanie w publicznym miejscu przed właściwym spotkaniem. Weryfikacja jest ważna bo portale lifestyle przyciągają fake profiles, scammers i osoby które kłamią na temat swojego stanu cywilnego (np. żonaci którzy ukrywają lifestyle przed partnerem). Jeśli ktoś odmawia jakiejkolwiek weryfikacji i naciska na szybkie spotkanie — to red flag. W Polsce video verification przez WhatsApp lub Signal jest standardem przed pierwszym spotkaniem z nową parą.', category: 'Swinging / Lifestyle', examples: ['Zanim się spotkamy, prosimy o weryfikację video — to standard w naszym środowisku.'] },
  { term: 'Chemistry', slug: 'chemistry', definition: 'Chemistry (chemia) to wzajemna atrakcja i flow między parami lub osobami w lifestyle. Chemia musi być żeby zabawa była dobra — bez niej nawet technicznie poprawna sesja będzie niezręczna. "No chemistry" to grzeczny, akceptowany w lifestyle sposób na odmowę bez podawania innych przyczyn. Nie wymaga wyjaśnień, nikt nie powinien się obrażać ani pytać dlaczego. Chemistry jest albo jest albo jej nie ma — i nie da się jej wymusić. Jeśli czujesz chemistry z partnerami ale Twój partner nie — uszanujcie to i nie idźcie dalej. Chemistry musi działać dla obojga z pary. Brak chemii to nie ocena atrakcyjności drugiej pary — po prostu energie się nie spotkały.', category: 'Swinging / Lifestyle', examples: ['"Nie ma chemii" — polite way to decline. Doesn\'t mean anything is wrong.'] },
  { term: 'Reclaim Sex', slug: 'reclaim-sex', definition: 'Reclaim sex (seks odzyskujący) to seks z Twoim stałym partnerem bezpośrednio po zabawie z innymi osobami. Dla wielu par jest to rytuał który zamyka wieczór i potwierdza ich wyjątkową więź — niezależnie od tego co się wydarzyło wcześniej. Reclaim sex mówi: "to co mamy między sobą jest inne i ważniejsze niż wszystko co zdarzyło się tej nocy." Nie jest obowiązkowy — nie każda para go potrzebuje. Ale dla wielu, szczególnie na początku przygody z lifestyle, jest bardzo ważnym elementem emocjonalnego bezpieczeństwa. Bywa też po prostu przyjemny — często para wraca do siebie z nową energią i podnieceniem. Rozmawiajcie o tym czego potrzebujecie po imprezie — to ważna część debriefingu.', category: 'Swinging / Lifestyle', examples: ['Po każdej imprezie lifestyle zawsze mamy swój czas — reclaim sex jest ważną częścią naszego rytuału.'] },
  { term: 'GGG (Good, Giving, Game)', slug: 'ggg', definition: 'GGG to filozofia seksualna stworzona przez amerykańskiego felietonistę Dana Savage\'a, która trafiła do lifestyle community jako codzienny kodeks postępowania. G1 — Good: bądź dobry w łóżku, dbaj o swoje umiejętności i bycie przyjemnym partnerem. G2 — Giving: dawaj partnerowi przyjemność nie tylko wtedy gdy Ty też na tym zyskujesz — altruizm seksualny. G3 — Game: bądź otwarty na wypróbowanie nowych rzeczy, nawet jeśli nie wiesz czy Ci się spodoba — w granicach rozsądku oczywiście. GGG to postawa która sprawia że jesteś partnerem z którym inni chcą grać. W lifestyle community GGG jest cenione bo odróżnia osoby które traktują swinging jako wspólną zabawę od tych którzy tylko "biorą".', category: 'Swinging / Lifestyle', examples: ['GGG to postawa którą ceni lifestyle community — wzajemność i otwartość.'] },
  { term: 'Meet & Greet', slug: 'meet-and-greet', definition: 'Meet & Greet to towarzyskie spotkanie lifestyle community w normalnym publicznym miejscu — kawiarni, restauracji, barze. Bez seksu, bez zabawy, tylko poznawanie ludzi i rozmowa. Dla newbies Meet & Greet jest idealnym pierwszym krokiem — pozwala poczuć atmosferę społeczności, poznać twarze i osobowości przed wejściem do klubu, zadać pytania w bezpiecznym środowisku. Dla doświadczonych par to sposób na rozszerzenie kręgu znajomych i sprawdzenie chemii z potencjalnymi partnerami bez presji. M&G bywają organizowane przez lifestyle clubs przed ich imprezami, albo spontanicznie przez grupy na Discordzie lub Telegramie. Nie musisz się do niczego zobowiązywać po Meet & Greet.', category: 'Swinging / Lifestyle', examples: ['Zaczęliśmy od Meet & Greet — pozwoliło nam poznać kilka par przed pójściem do klubu.'] },
  { term: 'Hotel Takeover', slug: 'hotel-takeover', definition: 'Hotel Takeover to wydarzenie gdzie lifestyle group lub organizator rezerwuje większość pokoi w hotelu — zazwyczaj na cały weekend. Cały hotel lub jego duża część staje się przestrzenią lifestyle: prywatne parties w pokojach, imprezy przy basenie, wspólne kolacje, playrooms w wyznaczonych pokojach. Hotel Takeover to intensywniejsze doświadczenie niż jednorazowe wyjście do klubu — żyjesz w bańce lifestyle przez 48-72 godziny, spotykasz te same osoby przy śniadaniu i przy basenie. Tworzy silne poczucie wspólnoty. Popularne destynacje takeover w Europie to m.in. hotele w Czechach, Hiszpanii i Turcji. W Polsce sporadycznie organizowane przez większe środowiska.', category: 'Swinging / Lifestyle', examples: ['Hotel takeover to intensywniejsze doświadczenie niż klub — cały weekend w jednym miejscu.'] },
  { term: 'House Party', slug: 'house-party', definition: 'House party to impreza lifestyle zorganizowana w prywatnym domu lub mieszkaniu — zazwyczaj tylko na zaproszenie, dla sprawdzonych, znanych osób. Bardziej kameralna i intymna niż klub: mniej osób, większe poczucie bezpieczeństwa, znasz prawie każdego. Atmosfera jest często bardziej swobodna i domowa — koktajle w salonie, muzyka, rozmowy, a potem może zabawa. House party są też bardziej elastyczne jeśli chodzi o zasady — każdy gospodarz ustala własne. Wejście na dobrą house party wymaga referencji lub dłuższego bycia w społeczności. To naturalna ewolucja dla par które wychodzą poza etap "klub dla obcych" i budują swój własny krąg zaufanych.', category: 'Swinging / Lifestyle', examples: ['House party są kameralne i przyjazne — znasz prawie każdego.'] },
  { term: 'Lifestyle Friendly', slug: 'lifestyle-friendly', definition: 'Lifestyle friendly to określenie hotelu, resortu, wynajmowanego apartamentu lub innego lokalu który jest świadomy i akceptujący wobec lifestyle gości — nie wyrzuci Cię za pocałunki z kimś innym niż partner, nie będzie dziwnie patrzeć na kilka dorosłych osób wchodzących do jednego pokoju, nie będzie zadawać pytań. Lifestyle friendly hotele i resorty popularne są szczególnie w Europie Południowej — Hiszpania, Turcja, Grecja mają wiele kompleksów które dyskretnie obsługują lifestyle turystów. W Polsce wynajmowane prywatnie apartamenty lub domy na house party są częstszą alternatywą. Jeśli szukasz lifestyle friendly noclegu: przeczytaj recenzje na lifestyle forach, zapytaj w swojej lokalnej społeczności — polecenia od kogoś kto już był są najlepszym źródłem.', category: 'Swinging / Lifestyle', examples: ['Szukamy lifestyle friendly hotelu na weekend — potrzebujemy swobody.'] },
  { term: 'On-premise', slug: 'on-premise', definition: 'On-premise to określenie dla wydarzeń lub klubów gdzie aktywność seksualna odbywa się na miejscu — jest dedykowana strefa zabaw (playroom, darkroom, specjalne pokoje). Wchodzisz, bawiasz się, wychodzisz. Typowe lifestyle clubs są on-premise. On-premise wymaga od uczestników gotowości na to że mogą być obserwowani lub że zobaczą innych w trakcie zabawy — nawet jeśli sami nie uczestniczą. Dobry on-premise venue ma jasne zasady co do playrooms: kto może wchodzić, jak prosić o zgodę, jak odmówić. Dla newbies on-premise może być na początku przytłaczające — nic złego jest w tym żeby przyjść, poobserwować i nie brać udziału w zabawie pierwszego razu.', category: 'Swinging / Lifestyle', examples: ['To on-premise event — jest specjalna strefa play na piętrze.'] },
  { term: 'Off-premise', slug: 'off-premise', definition: 'Off-premise to wydarzenie towarzyskie lifestyle gdzie na miejscu NIE ma aktywności seksualnej. Flirty, dotykanie, tańczenie — ok. Seks — umawiasz się prywatnie i idziesz gdzie indziej. Off-premise to zazwyczaj Meet & Greet, cocktail party lub kolacja — nacisk na poznanie ludzi, rozmowę i sprawdzenie chemii. Dla newbies off-premise jest świetnym pierwszym krokiem bo pozwala wejść do lifestyle community bez presji od razu wchodzenia w zabawę. Dla doświadczonych par off-premise to sposób na rozszerzenie kręgu znajomych i "scouting" bez angażowania się w tę samą noc. Off-premise eventy są też łatwiejsze do organizacji — żaden lokal nie musi mieć specjalnych zezwoleń.', category: 'Swinging / Lifestyle', examples: ['To off-premise party — Meet & Greet, poznajemy się, a potem każdy układa się osobno.'] },
  { term: 'No Means No', slug: 'no-means-no', definition: '"No means no" to absolutna zasada lifestyle community — i szerzej, całego kodu postępowania wobec zgody i granic. Jeśli ktokolwiek mówi "nie", odsuwa się, wydaje się nieswobo lub w jakikolwiek sposób sygnalizuje brak chęci — wszystko się natychmiastowo zatrzymuje. Brak negocjacji, brak "ale może jednak", brak urazy. W lifestyle clubs naruszenie tej zasady skutkuje stałym wyrzuceniem i czarną listą w całej społeczności. "No means no" dotyczy zarówno jawnej odmowy jak i braku entuzjazmu — dobry uczestnik nie czeka na twarde "nie", ale aktywnie sprawdza czy partner/partnerka chce kontynuować. Lifestyle culture kładzie duży nacisk na enthusiastic consent — zgoda musi być aktywna i entuzjastyczna, nie tylko brak odmowy.', category: 'Swinging / Lifestyle', examples: ['No means no to absolutna zasada w lifestyle community — szanujemy granice zawsze.'] },
  { term: 'Lifestyle Club / Swinger Club', slug: 'lifestyle-club', definition: 'Lifestyle club (inaczej swinger club) to lokal gdzie pary i czasem single spotykają się żeby flirtować, poznawać innych i uprawiać seks w bezpiecznym, dyskretnym środowisku. Typowy lifestyle club ma kilka stref: bar i lounge (normalna rozmowa i flirt), dance floor, playrooms (otwarte lub prywatne), często jacuzzi lub sauna. W Polsce działa kilka dobrze znanych klubów: Lava (Warszawa), Elysium (Warszawa), Heaven (Warszawa), Bordeaux (Kraków), Jacuzzi Club — i wiele innych działających dyskretnie w różnych miastach. Lifestyle club jest bezpieczniejszy niż przypadkowe spotkania online: jest ochrona, personel, jasne zasady, i środowisko które samo się pilnuje. Pierwsze wejście do klubu może być stresujące — mało kto żałuje że spróbował.', category: 'Swinging / Lifestyle', examples: ['Lifestyle club to bezpieczna przestrzeń gdzie wszystko odbywa się za zgodą i w dyskrecji.'] },
  { term: 'Single Female (SF)', slug: 'single-female', definition: 'Single Female (SF) to kobieta bez stałego partnera aktywna w lifestyle scene. SF są w lifestyle community wyjątkowo mile widziane — popyt na SF znacznie przewyższa podaż. W większości lifestyle clubs SF wchodzą za darmo lub po mocno obniżonej cenie. Bycie SF w lifestyle to duża swoboda: możesz wybierać z kogo i z czego korzystać, nie masz presji "mój partner też musi być zainteresowany". Wiele kobiet które zaczynały jako SF z czasem wchodzi w związki i przechodzi do sceny jako para. SF bywa też szukana przez konkretne pary do trójkąta (FFM). Jeśli jesteś SF i zastanawiasz się nad lifestyle: Meet & Greet to bezpieczny start gdzie poznasz scen bez zobowiązań.', category: 'Swinging / Lifestyle', examples: ['Single female zawsze są mile widziane w lifestyle clubs.'] },
  { term: 'Single Male (SM)', slug: 'single-male', definition: 'Single Male (SM) to mężczyzna bez stałej partnerki aktywny w lifestyle scene — i sytuacja SM jest zupełnie inna niż SF. SM są zazwyczaj najmniej pożądaną kategorią w lifestyle: wiele klubów limituje liczbę wejść dla SM, pobiera wyższe ceny (często 3-5x więcej niż para), lub w ogóle nie wpuszcza SM na pewne eventy. Nie dlatego że SM są gorsi — ale dlatego że chętnych SM jest ogromnie więcej niż zapotrzebowania. Para szuka do MFM konkretnego mężczyzny z którym ma chemię — nie pierwszego chętnego z listy. Dla SM który chce wejść w lifestyle: buduj reputację i relacje stopniowo, bądź GGG, szanuj zasady, nie naciskaj. Zaufanie budowane jest latami — w lifestyle nie ma drogi na skróty.', category: 'Swinging / Lifestyle', examples: ['Dla single male lifestyle scene jest trudniejsza — wiele klubów ma limit lub wyższe ceny.'] },

  // === BDSM / KINK ===
  { term: 'BDSM', slug: 'bdsm', definition: 'BDSM to skrót-parasol który obejmuje kilka nakładających się praktyk: B&D (Bondage & Discipline — wiązanie i dyscyplina), D/s (Dominance & Submission — dynamika dominacji i uległości), S&M (Sadism & Masochism — czerpanie przyjemności z zadawania lub odbierania bólu). Nie każda osoba w BDSM praktykuje wszystkie elementy — ktoś może lubić bondage ale nie mieć żadnego zainteresowania D/s, ktoś inny żyje w 24/7 power exchange ale nigdy nie używa lin. BDSM jest starszy niż słowo BDSM — praktyki te istniały w kulturze od wieków, po prostu bez nazwy. Dziś BDSM community jest dobrze zorganizowane, ma własną etykę (SSC, RACK), własne przestrzenie (dungeony, kluby) i rozbudowany kod postępowania oparty na consensie. Największy mit o BDSM: że to trauma lub patologia. Badania pokazują że osoby praktykujące BDSM mają średnio wyższy poziom dobrostanu psychicznego niż populacja ogólna.', category: 'BDSM / Kink', examples: ['BDSM wymaga dokładnego omówienia granic przed każdą sesją.'] },
  { term: 'Kink', slug: 'kink', definition: 'Kink to szerokie określenie dla wszystkiego co wykracza poza konwencjonalny (vanilla) seks. Jest szersze niż BDSM — obejmuje BDSM ale też fetisze, role play, specyficzne sytuacje lub przedmioty które dla danej osoby są erotyczne. Przykłady kink: impact play (bicie otwartą dłonią, flogger), rope bondage, voyeuryzm, exhibicjonizm, age play, pet play, foot worship, latex, uniform play — lista jest praktycznie nieograniczona. Kink to preferencja seksualna, nie zaburzenie. Jedynym kryterium "ok czy nie ok" jest konsens wszystkich stron i brak krzywdy osobom trzecim. Ważna zasada: twój kink nie musi podobać się innym żeby był ok. Równie ważna: twój kink nie zmusza innych do uczestniczenia.', category: 'BDSM / Kink', examples: ['Każdy ma swoje kinki — ważne żeby omówić je z partnerem.'] },
  { term: 'Safeword', slug: 'safeword', definition: 'Safeword to umówione wcześniej słowo (lub sygnał niewerbalny) które natychmiastowo przerywa aktywność BDSM — bez dyskusji, bez negocjacji, bez "ale zaraz skończymy". Safeword jest używany gdy: intensywność przekroczyła granicę, pojawiła się nieoczekiwana emocja, coś boli w zły sposób, lub po prostu chcesz stop. Dobry Dom/Top nigdy nie kwestionuje użycia safeword — to sygnał któremu ufa się bezwarunkowo. Klasyczne safeword: "czerwony" (stop), "żółty" (zwolnij), lub dowolne słowo które nie pojawi się przypadkowo w scenie (stąd popularne "ananasy" — nikt nie mówi "ananasy" przypadkowo podczas BDSM). Sygnały niewerbalne (np. upuszczenie przedmiotu) ważne gdy usta są zajęte lub związane.', category: 'BDSM / Kink', examples: ['Naszym safeword jest "ananasy" — jak tylko je powie, wszystko zatrzymujemy.'] },
  { term: 'Red / Yellow / Green', slug: 'red-yellow-green', definition: 'Red/Yellow/Green to popularny trzystopniowy system safeword wzorowany na sygnalizacji świetlnej — prosty, intuicyjny i zrozumiały nawet w środku intensywnej sceny. Red = stop natychmiast, wszystko się kończy. Yellow = zwolnij, potrzebuję chwili, coś wymaga uwagi — ale nie koniec. Green = wszystko ok, kontynuuj. Siła tego systemu to gradacja: nie musisz wybierać między "wszystko ok" a "ratunku" — jest środkowa opcja na lekki dyskomfort lub potrzebę korekty. Dom może też aktywnie pytać "kolor?" podczas sceny żeby sprawdzić stan suba — sub odpowiada jedno słowo. System działa też gdy sub jest w stanie silnych emocji i ciężko mu formułować zdania — jedno słowo wystarczy.', category: 'BDSM / Kink', examples: ['Używamy systemu Red/Yellow/Green — Yellow nie znaczy stop, tylko "daj mi chwilę".'] },
  { term: 'SSC (Safe, Sane, Consensual)', slug: 'ssc', definition: 'SSC — Safe, Sane, Consensual — to klasyczna filozofia BDSM sformułowana w latach 80. jako odpowiedź na pytanie "jak odróżnić zdrowe BDSM od przemocy". Trzy filary: Safe (bezpieczne) — minimalizujesz ryzyko fizyczne i emocjonalne, znasz techniki, masz safewords. Sane (świadome) — jesteś trzeźwy, w dobrej kondycji psychicznej, podejmujesz decyzje z czystą głową. Consensual (za zgodą) — wszyscy uczestnicy świadomie i dobrowolnie wyrażają zgodę i mogą ją w każdej chwili wycofać. SSC jest dobrym punktem wyjścia szczególnie dla osób zaczynających w BDSM. Krytyka SSC: słowo "safe" jest zbyt absolutne — żadna intensywna aktywność nie jest stuprocentowo bezpieczna. Stąd powstało RACK jako uzupełnienie.', category: 'BDSM / Kink', examples: ['SSC to klasyczna filozofia — wiele środowisk uzupełnia ją nowszymi podejściami jak RACK.'] },
  { term: 'RACK (Risk-Aware Consensual Kink)', slug: 'rack', definition: 'RACK — Risk-Aware Consensual Kink — to nowsza filozofia BDSM która wyszła z krytyki SSC. Zamiast "safe" (bezpieczne) mówi "risk-aware" (świadome ryzyka) — bo niektóre praktyki BDSM niosą inherentne ryzyko którego nie da się całkowicie wyeliminować (np. breath play, edgeplay, zaawansowane bondage). RACK nie zachęca do lekceważenia bezpieczeństwa — zachęca do pełnej świadomości: co może pójść nie tak, jakie są statystyki, jak zminimalizować ryzyko, i świadomej decyzji obu stron. To bardziej realistyczne podejście dla doświadczonych praktyków którzy chcą eksplorować zaawansowane praktyki. Dla beginnerów SSC jest prostszym punktem startowym — RACK to ewolucja wraz z nabywaniem doświadczenia.', category: 'BDSM / Kink', examples: ['RACK pozwala na bardziej zaawansowane praktyki przy pełnej świadomości ryzyka.'] },
  { term: 'Dom / Domina', slug: 'dom-domina', definition: 'Dom (lub Domme/Domina) to osoba pełniąca rolę dominującą w dynamice D/s — bierze kontrolę, ustala zasady, wydaje polecenia, prowadzi scene. Dom = mężczyzna dominant, Domme lub Domina = kobieta dominant. To nie jest wyłącznie kwestia twardości czy surowości — dobry Dom to przede wszystkim ktoś kto słucha, obserwuje swojego suba i bierze pełną odpowiedzialność za jego dobrostan podczas sceny. Warianty: Daddy Dom (nurturing, ciepły, opiekuńczy), Master/Mistress (bardziej formalny, strict), Owner (intensywna dynamika kontroli). Bycie Domem to odpowiedzialność — sub powierza Ci swoje bezpieczeństwo i zaufanie. To przywilej, nie tylko władza.', category: 'BDSM / Kink', examples: ['Jako Domme, ona ustala zasady i granice ich sesji.'] },
  { term: 'Sub / Submissive', slug: 'sub', definition: 'Sub (submissive) to osoba pełniąca rolę uległą w dynamice D/s — oddaje kontrolę Domowi, wykonuje polecenia, jest prowadzona przez scene. Kluczowa rzecz którą warto rozumieć: bycie subem to aktywny, świadomy wybór wymagający ogromnej siły i zaufania — nie jest oznaką słabości, braku pewności siebie ani ofiary. W BDSM mówi się że "sub holds the real power" — to sub ustala granice, ma safeword i może zakończyć scene w każdej chwili. Dom może tylko tyle ile sub pozwoli. Bycie subem daje wiele osób głęboki spokój i poczucie bezpieczeństwa — oddanie kontroli komuś zaufanemu bywa ogromnym odciążeniem. Nie mylić suba z osobą która po prostu jest pasywna seksualnie — to nie to samo.', category: 'BDSM / Kink', examples: ['On chętnie przyjmuje rolę suba w ich dynamice — to jego świadomy wybór.'] },
  { term: 'Switch', slug: 'switch', definition: 'Switch to osoba która może wchodzić zarówno w rolę dominującą jak i uległą — w zależności od partnera, nastroju, kontekstu lub sceny. Z jedną osobą jest Domem, z inną Subem, a z kolejną może płynnie przełączać się w trakcie tej samej sceny. Switch nie jest "niezdecydowany" ani w pół drogi — to pełnoprawna tożsamość BDSM z własnymi preferencjami i dynamiką. Wiele switchy odkrywa że są switche przez eksplorację — zaczynają jako sub, próbują dominować i odkrywają że lubią obie strony. Switch/Switch dynamika (oboje są switche) bywa szczególnie ciekawa — role mogą się naturalnie zmieniać w odpowiedzi na energię.', category: 'BDSM / Kink', examples: ['Jako switch lubi zarówno dowodzić jak i być prowadzona.'] },
  { term: 'Top / Bottom', slug: 'top-bottom', definition: 'Top i Bottom to określenia ról w BDSM które opisują kto "robi" a kto "dostaje" — i ważne: to nie to samo co Dom i Sub. Top to osoba która wykonuje aktywność: wiąże, uderza, penetruje, kontroluje tempo. Bottom to osoba która przyjmuje: jest wiązana, przyjmuje uderzenia, jest penetrowana. Różnica od Dom/Sub: Dom/Sub to dynamika psychologiczna i power exchange. Top/Bottom to opis fizycznej roli w scenie. Można być "service top" — robisz wszystko technicznie (wiążesz, uderzasz) ale to Sub emocjonalnie prowadzi scenę i decyduje o kierunku. Można być "power bottom" — przyjmujesz fizycznie ale masz kontrolę psychologiczną. Te kombinacje są normalną częścią BDSM.', category: 'BDSM / Kink', examples: ['Można być "service top" — robisz wszystko ale Sub ma kontrolę nad sceną.'] },
  { term: 'Power Exchange', slug: 'power-exchange', definition: 'Power exchange (wymiana władzy) to przekazanie kontroli i władzy z jednej osoby (Sub) na drugą (Dom) — świadomie, dobrowolnie i tymczasowo lub na stałe. To psychologiczne serce BDSM: nie chodzi tylko o to co się fizycznie robi, ale o dynamikę kto prowadzi a kto jest prowadzony. Power exchange może trwać wyłącznie podczas sceny i kończyć się gdy scene się kończy. Może też wychodzić poza sesje i wchodzić w codzienne życie (D/s lifestyle): Dom decyduje co Sub je, co zakłada, kiedy może spać. W ekstremalnej formie Total Power Exchange (TPE) Sub oddaje kontrolę nad praktycznie wszystkimi aspektami życia. TPE wymaga ogromnego zaufania, długiej historii i bardzo solidnych ram bezpieczeństwa.', category: 'BDSM / Kink', examples: ['Power exchange to nie przemoc — to świadome, negocjowane oddanie i przyjęcie władzy.'] },
  { term: 'Scene', slug: 'scene', definition: 'Scene to konkretna, zamknięta sesja BDSM — ma negocjowany początek, przebieg i wyraźny koniec. Poza scene Dom i Sub mogą być zwykłymi równorzędnymi partnerami; w trakcie scene wchodzą w ustaloną dynamikę. Długość sceny bywa różna: od kilkunastu minut do kilku godzin. Dobra scene zaczyna się od negocjacji (co robimy, co jest off-limits, jakie safeword), przechodzi przez właściwą aktywność prowadzoną przez Dom, i kończy wyraźnym sygnałem zakończenia — po którym następuje aftercare. Pojęcie scene używane jest też szerzej: "scena BDSM" to cała community i kultura wokół BDSM.', category: 'BDSM / Kink', examples: ['Scene zawsze zaczyna się od negocjacji — co będziemy robić, co jest off-limits, jakie safeword.'] },
  { term: 'Aftercare', slug: 'aftercare', definition: 'Aftercare to opieka i wsparcie po intensywnej scenie BDSM — i jest równie ważny jak sama scena. BDSM angażuje silne emocje, adrenalinę i endorfiny; gdy scene się kończy ciało i psychika potrzebują czasu żeby wrócić do stanu normalnego. Aftercare wygląda różnie dla różnych osób: przytulanie, koc, ciepły napój, cicha rozmowa, lub po prostu bliskość fizyczna bez słów. Dom ma obowiązek zapewnić aftercare — to nie opcja. Sub powinien komunikować czego potrzebuje po scene, bo potrzeby bywają różne. Zaniedbanie aftercare jest poważnym błędem w BDSM ethics i może prowadzić do sub dropu lub trwałego emocjonalnego urazu.', category: 'BDSM / Kink', examples: ['Po każdej sesji poświęcamy godzinę na aftercare — przytulanie i rozmowę o tym co przeżyliśmy.'] },
  { term: 'Sub Drop / Dom Drop', slug: 'sub-drop', definition: 'Sub drop to emocjonalny i fizyczny kryzys który może pojawić się po intensywnej scenie — zazwyczaj kilka godzin lub nawet dzień lub dwa po fakcie. Wynika ze gwałtownego spadku endorfin, adrenaliny i oksytocyny które były wysokie podczas sceny. Objawy: nieuzasadniony smutek, płaczliwość, poczucie pustki lub odłączenia, lęk, zmęczenie. Sub drop może zaskoczyć — scene była super, a następnego dnia płaczesz bez powodu. Dom Drop (rzadziej omawiany) to podobny stan u osoby dominującej — ciężar odpowiedzialności za scenę i drugą osobę może generować własny rodzaj emocjonalnego wyczerpania. Lekarstwo: aftercare, kontakt z Domem, odpoczynek, ciepłe jedzenie, rozmowa.', category: 'BDSM / Kink', examples: ['Dzień po intensywnej scene poczułam sub drop — byłam smutna bez powodu. Mój Dom był ze mną.'] },
  { term: 'Subspace', slug: 'subspace', definition: 'Subspace to zmieniony stan świadomości który doświadcza Sub podczas intensywnej sceny. Opisywany jako uczucie "high", głębokiego spokoju, euforii, oderwania od codzienności, poczucia bezpieczeństwa i całkowitego oddania. Wynika z kombinacji zaufania, intensywnych bodźców fizycznych i zalewu endorfin i oksytocyny. W subspace Sub może być non-verbal, może mieć osłabiony zmysł bólu (co oznacza że nie czuje gdy coś przekracza bezpieczną granicę), może nie być w stanie użyć safeword. To sprawia że Dom musi być szczególnie uważny i obserwować ciało i reakcje suba — nie tylko czekać na słowną komunikację. Wyjście z subspace może być nagłe i dezorientujące — stąd ważność aftercare.', category: 'BDSM / Kink', examples: ['Gdy wchodzi w subspace, Dom musi być extra uważny — ona może nie być w stanie powiedzieć stop.'] },
  { term: 'Negocjacja', slug: 'negocjacja-bdsm', definition: 'Negocjacja przed scene to obowiązkowa rozmowa w której wszyscy uczestnicy ustalają co będzie się dziać, jakie są granice i jak zapewnić bezpieczeństwo. Dobra negocjacja BDSM obejmuje: hard limits (czego absolutnie nie robimy), soft limits (co wymaga dodatkowej rozmowy), preferowane aktywności, safeword i sygnały awaryjne, potrzeby aftercare, ewentualne triggery, stan zdrowia fizycznego (kontuzje, problemy z krążeniem przy bondage). Negocjacja nie niszczy spontaniczności — daje ramy w których spontaniczność jest bezpieczna. Im lepiej negocjacja, tym swobodniej Dom może prowadzić scene bez ciągłego pytania o zgodę w środku. Negocjacja musi być aktualizowana — granice zmieniają się z czasem i doświadczeniem.', category: 'BDSM / Kink', examples: ['Negocjacja przed scene to obowiązek — bez niej nie zaczynamy.'] },
  { term: 'Hard Limit', slug: 'hard-limit', definition: 'Hard limit to absolutna, nieprzekraczalna granica — rzecz której nie robisz nigdy, niezależnie od kontekstu, nastroju, zaufania do partnera czy głębokości sceny. Przykłady: "nigdy blood play", "nigdy scat", "nigdy bez prezerwatywy", "nigdy z nagrywaniem". Hard limity nie wymagają uzasadnienia — wystarczy że są. Dom który narusza hard limit — nawet "przez przypadek", nawet gdy sub był w subspace — dopuścił się poważnego naruszenia consensu. Hard limity są ustalane podczas negocjacji i zapisywane mentalnie lub dosłownie. Mogą się zmieniać z czasem (coś co było hard limitem może stać się soft limitem lub odwrotnie) — ale zmiana musi być świadomą decyzją podjętą poza scene, nie czymś co się "wydarza" w środku.', category: 'BDSM / Kink', examples: ['Hard limit to nieprzekraczalna linia — nawet w trakcie scene, nawet jeśli sub jest w subspace.'] },
  { term: 'Soft Limit', slug: 'soft-limit', definition: 'Soft limit to granica "może, zależy" — rzecz której zazwyczaj nie robisz, ale która nie jest absolutnym nie. Może być ok w odpowiednich warunkach: z konkretną osobą, po dłuższej historii zaufania, z dodatkową rozmową, powoli i stopniowo. Przykład: spanking może być soft limitem dla kogoś kto nigdy nie próbował — nie wiem czy mi się spodoba, ale jestem otwarta na wypróbowanie z Tobą w kontrolowanych warunkach. Soft limity są ważnym narzędziem do eksploracji — pozwalają rozszerzać granice bezpiecznie. Dobry Dom obserwuje soft limity z szacunkiem: nie naciska, nie "technicznie masz rację że powiedziałaś może", ale czeka na wyraźne zaproszenie.', category: 'BDSM / Kink', examples: ['Spanking to mój soft limit — nie z każdym, ale z Tobą, po negocjacji, ok.'] },
  { term: 'Bondage', slug: 'bondage', definition: 'Bondage to ograniczanie ruchu partnera — za zgodą i w celach erotycznych lub estetycznych. Formy bondage są bardzo różne: rope bondage (shibari, kinbaku — artystyczne wiązanie linami), kajdanki i obroże (cuffs), taśma bondage, specjalne uprzęże (harness), a na zaawansowanym poziomie suspension (powieszenie w powietrzu). Bondage tworzy intensywną dynamikę zaufania — osoba wiązana dosłownie oddaje kontrolę nad swoim ciałem. Wymaga znajomości anatomii (nerwy, krążenie) i szybkiego dostępu do nożyczek ratunkowych (zawsze miej nożyczki przy sobie). Nie zostawiaj osoby wiązanej samej nawet na chwilę. Bondage może być czysto estetyczny bez elementów seksualnych — wiele sesji shibari to artystyczna fotografia.', category: 'BDSM / Kink', examples: ['Bondage to nie tylko wiązanie — to zaufanie i estetyka.'] },
  { term: 'Shibari / Kinbaku', slug: 'shibari', definition: 'Shibari i kinbaku to japońskie formy rope bondage z bogatą historią sięgającą XVII-wiecznych technik wiązania jeńców (hojōjutsu). Shibari (dosłownie "wiązanie") to termin ogólny, używany głównie na Zachodzie dla dekoracyjnego, artystycznego wiązania linami. Kinbaku (dosłownie "ciasne wiązanie") to termin bardziej erotyczny i intensywny, skupiony na uczuciu ograniczenia i psychologicznej dynamice. W praktyce terminy są używane zamiennie. Shibari/kinbaku to dziś osobna dziedzina z własnymi artystami, galeriami i festiwalami (w Europie m.in. Eurix w Amsterdamie). W Polsce rośnie scena — warsztaty dostępne w Warszawie, Krakowie, Wrocławiu. Nauka shibari wymaga czasu: zacznij od podstaw, ucz się od doświadczonych rigerów, nie improwizuj suspension bez lat praktyki.', category: 'BDSM / Kink', examples: ['Shibari to sztuka — sesje mogą być artystyczne, bez kontekstu seksualnego.'] },
  { term: 'Impact Play', slug: 'impact-play', definition: 'Impact play to uderzanie partnera w celach erotycznych — czerpanie przyjemności z zadawania lub odbierania bólu w kontrolowanej formie. Formy: spanking (otwarta dłoń na pośladkach), flogging (bat z wieloma końcówkami), paddling (łopatka), caning (trzcina). Każde narzędzie daje inny rodzaj odczucia: flogger to rozległy, ciepły ból; cane to intensywny, punktowy. Kluczowe zasady anatomiczne: bezpieczne strefy to pośladki, górne uda i górne plecy (mięśnie). NIE uderzamy w głowę, szyję, dolny odcinek kręgosłupa, nerki i stawy. Zacznij zawsze od najlżejszej formy — ręki — zanim wprowadzisz narzędzia. Intensywność buduj stopniowo. Rozmawiaj z partnerem co czuje po każdym uderzeniu, szczególnie na początku.', category: 'BDSM / Kink', examples: ['Impact play zaczynamy od lekkiego spanking ręką — potem ewoluujemy w kierunku flogger.'] },
  { term: 'Brat', slug: 'brat', definition: 'Brat to sub który jest celowo nieposłuszny, przekorny i prowokujący — nie dlatego że nie chce się podporządkować, ale dlatego że lubi "zasłużyć" na reakcję Doma. Klasyczne zachowania brata: "a zmuś mnie", przewracanie oczami, ignorowanie poleceń, droczenie się, wychodzenie poza granice regulaminowe. To zaproszenie do gry, nie bunt. Brat Tamer to Dom który wie jak sobie z tym poradzić — zazwyczaj z połączeniem zimnej krwi i skutecznej "kary" której brat tak naprawdę pragnie. Ważne: bratowanie się działa tylko gdy Dom jest na to gotowy i lubi tę dynamikę. Dom który tego nie lubi nie powinien pracować z bratami — frustracja z obu stron gwarantowana.', category: 'BDSM / Kink', examples: ['"Nie możesz mi kazać" — klasyczne zachowanie brata. Dom wie, że to zaproszenie.'] },
  { term: 'Collar', slug: 'collar', definition: 'Collar (obroża) w kontekście BDSM to symbol relacji D/s — nie tylko dodatek do sceny. Istnieją różne rodzaje: Play collar zakładana tylko podczas scene i zdejmowana po; Day collar dyskretna, noszona na co dzień jako prywatny symbol relacji (często wygląda jak normalny naszyjnik); Permanent collar symbol głębokiego, długoterminowego zaangażowania w dynamikę D/s — w społeczności BDSM traktowana z taką powagą jak obrączka ślubna. Rytuał wręczenia permanent collar (collaring ceremony) bywa celebrowany równie uroczyście jak zaręczyny. Zdjęcie collara przez Sub bez zgody Doma (lub odwrotnie) to poważny sygnał w relacji. Collar zawsze powinna być wygodna i bezpieczna — nigdy zbyt ciasna, zawsze z możliwością szybkiego zdjęcia.', category: 'BDSM / Kink', examples: ['Otrzymanie permanent collar to poważny krok w D/s relationship — traktowany jak rytuał zaręczyn.'] },
  { term: 'Dungeon', slug: 'dungeon', definition: 'Dungeon to przestrzeń wyposażona specjalnie do aktywności BDSM — może być w prywatnym domu, w klubie kink lub w specjalnym centrum. Typowe wyposażenie: krzyż św. Andrzeja (X-frame do przywiązywania stojącej osoby), ławka do spanking, stół medyczny, klatka, drabinka do bondage, punkty zawieszenia w suficie do suspension. Dobry dungeon ma też: apteczkę, nożyczki ratunkowe przy każdym stanowisku bondage, czyste podkłady jednorazowe, środki dezynfekcyjne. Dungeon w klubie ma zazwyczaj Dungeon Monitor (DM) — osobę która pilnuje bezpieczeństwa i zasad. DM może przerwać scene jeśli widzi naruszenie zasad lub zagrożenie. Prywatny dungeon w domu to marzenie wielu — budowany latami i z miłością.', category: 'BDSM / Kink', examples: ['W piwnicy mają prawdziwy dungeon z pełnym wyposażeniem.'] },
  { term: 'Munches', slug: 'munches', definition: 'Munch to nieformalne spotkanie towarzyskie kink community w zupełnie normalnym, publicznym miejscu — kawiarni, restauracji, barze. Zero play, zero obnoszenia się z kinkiem, zwykłe ubrania. Tylko rozmowy, networking i poznawanie ludzi ze sceny. Munche są idealnym pierwszym krokiem dla osób które chcą wejść w kink community ale nie wiedzą od czego zacząć — możesz przyjść, poznać ludzi, zadać pytania w bezpiecznym, neutralnym środowisku bez żadnej presji. W Polsce munche organizowane są regularnie w Warszawie, Krakowie, Wrocławiu i innych miastach — szukaj na Fetlife (największa platforma społecznościowa kink community) lub w lokalnych grupach na Telegramie.', category: 'BDSM / Kink', examples: ['Zaczęłam od munchów — poznałam środowisko zanim zdecydowałam się na play party.'] },
  { term: 'Play Party', slug: 'play-party', definition: 'Play party to prywatne lub półprywatne wydarzenie gdzie uczestnicy robią sceny BDSM — zazwyczaj w dungeonie lub odpowiednio wyposażonej przestrzeni. W odróżnieniu od lifestyle club nacisk jest na BDSM i kink, niekoniecznie na seks (choć może być). Zasady play party są zazwyczaj bardzo jasne i rygorystycznie przestrzegane: zgoda wymagana przy każdym kontakcie, pytaj zanim dotkniesz, szanuj safeword, nie przerywaj sceny innych bez powodu, nie gapaj się z odległości mniejszej niż X metrów. Play party zazwyczaj ma Dungeon Monitora który pilnuje zasad. Wejście na play party zazwyczaj wymaga referencji lub wcześniejszego poznania organizatora na munchu.', category: 'BDSM / Kink', examples: ['Play party różni się od lifestyle club — focus jest na BDSM, nie na seks.'] },
  { term: 'Edge Play', slug: 'edge-play', definition: 'Edge play to praktyki BDSM które balansują na granicy między intensywnym a potencjalnie niebezpiecznym — szara strefa gdzie ryzyko jest znacząco wyższe niż w standardowych aktywnościach. Przykłady: breath play (ograniczanie oddychania lub duszenie — jeden z najbardziej ryzykownych, bez "bezpiecznego" sposobu wykonania), knife play (noże przy ciele — tnące lub nie), fire play (ogień na skórze), blood play, extreme bondage i suspension. Edge play NIE jest dla początkujących. Wymaga lat doświadczenia w BDSM, głębokiego zaufania do partnera, znajomości anatomii i pierwszej pomocy, i świadomości że nawet przy wszelkich środkach ostrożności ryzyko pozostaje. RACK (nie SSC) jest właściwą filozofią dla edge play — pełna świadomość ryzyka, nie jego eliminacja.', category: 'BDSM / Kink', examples: ['Edge play to nie dla początkujących — wymaga lat doświadczenia i ekstremalnego zaufania.'] },
  { term: 'Primal Play', slug: 'primal-play', definition: 'Primal play to surowy, instynktowny, animalistyczny rodzaj interakcji seksualnej i BDSM — polowanie, szarpanie się, gryzienie, drapanie, warczenie, gonienie. Mniej negocjacji i protokołu niż w klasycznym BDSM, więcej ciała i instynktu. Role: Predator (poluje, dominuje, goni) i Prey (ucieka, chowa się, broni się). Primal play może być intensywnie fizyczne — dlatego wymaga dobrej kondycji, jasnych granic co do śladów (siniaki, zadrapania są częste) i zaufania że partner nie przekroczy granic nawet gdy scena staje się bardzo dzika. Dla wielu osób primal play to wyzwolenie z codziennej kontroli nad sobą — chwilowy powrót do czegoś bardziej zwierzęcego i mniej cywilizowanego.', category: 'BDSM / Kink', examples: ['Primal play to powrót do instynktów — mniej zasad, więcej intuicji i ciała.'] },
  { term: 'CNC (Consensual Non-Consent)', slug: 'cnc', definition: 'CNC — Consensual Non-Consent — to odgrywanie scenariusza w którym jeden uczestnik "udaje" że nie wyraża zgody, podczas gdy w rzeczywistości wcześniej w pełni świadomie na to przystał. W praktyce to odgrywanie rape fantasy, napaści lub porwania między zgadzającymi się dorosłymi z dokładnie negocjowanymi granicami i safeword. CNC jest kontrowersyjne nawet w kink community — wymaga najwyższego poziomu zaufania i najdokładniejszej negocjacji ze wszystkich praktyk. Konieczne: szczegółowe ustalenie co dokładnie będzie się dziać, co jest absolutnie off-limits, jak safeword będzie przekazywany (skoro "nie" jest częścią scenariusza — potrzebujesz alternatywnego sygnału), i pełny debrief po. CNC jest dla bardzo doświadczonych osób z ugruntowaną relacją.', category: 'BDSM / Kink', examples: ['CNC wymaga najdokładniejszej negocjacji ze wszystkich praktyk — co do szczegółu.'] },
  { term: 'Fetysz', slug: 'fetysz', definition: 'Fetysz to silna seksualna atrakcja do konkretnego przedmiotu, materiału, części ciała lub sytuacji — na tyle intensywna że jest niezbędna lub bardzo ważna dla seksualnej satysfakcji. To odróżnia fetysz od kinku: kink to preferowane, fetysz to konieczne. Przykłady popularnych fetyszów: foot fetish (stopy — jeden z najczęstszych), latex i skóra, pantyhose i pończochy, mundury, okulary, palenie papierosów. Fetysz jest formą orientacji seksualnej — nie da się go "wyleczyć" ani "wybrać". Badania pokazują że ludzka seksualność jest niesamowicie różnorodna i większość fetyszów jest zupełnie nieszkodliwa. Rozmowa z partnerem o fetyszach jest trudna ale konieczna — ukrywanie ważnej części swojej seksualności generuje frustrację po obu stronach.', category: 'BDSM / Kink', examples: ['Każdy ma swoje fetysze — ważne żeby je omówić z partnerem.'] },
  { term: 'Pet Play', slug: 'pet-play', definition: 'Pet play to forma role play gdzie Sub wciela się w rolę zwierzęcia domowego a Dom jest jego właścicielem (Owner). Najpopularniejsze warianty: puppy play (pies — szczekanie, łapki, miska, zabawa z piłką), kitten play (kot — mruczenie, niezależność, elegancja), pony play (koń — uprząż, powożenie, wystawy). Pet play może być seksualne — ale bardzo często nie jest i to nie jest jego główny punkt. Dla wielu uczestników pet play to głęboki relaks i ucieczka od dorosłych odpowiedzialności — bycie "tylko" pupilem który nie musi podejmować decyzji. Elementy: specjalne akcesoria (uszy, ogon, łapki, klatka, miska), protokół zachowania w roli, Owner który dba o zwierzę. Społeczność pet play jest bardzo przyjazna i często bardzo nieseksualna.', category: 'BDSM / Kink', examples: ['Pet play dla wielu jest relaksem i ucieczką od dorosłych obowiązków — nie zawsze chodzi o seks.'] },
  { term: 'Chastity', slug: 'chastity', definition: 'Chastity (czystość) to praktyka gdzie Sub nosi urządzenie czystości które fizycznie uniemożliwia osiągnięcie orgazmu lub dotykanie się bez zgody Doma. Dla mężczyzn: klatka na penisie (cock cage). Dla kobiet: pas cnoty. Dom trzyma klucz. Chastity to jeden z najbardziej intensywnych form długoterminowego power exchange — Dom kontroluje jedną z najbardziej fundamentalnych potrzeb biologicznych Suba. Może trwać godziny, dni, tygodnie lub miesiące. Strona psychologiczna jest często ważniejsza niż fizyczna: stałe przypomnienie o zależności od Doma, narastające napięcie seksualne, akt "uwolnienia" jako nagroda. Praktyczne uwagi: urządzenie musi być odpowiednio dopasowane (złe dopasowanie = urazy), regularnie sprawdzaj skórę i krążenie.', category: 'BDSM / Kink', examples: ['Chastity to długoterminowy power exchange — Dom kontroluje jedną z najbardziej intymnych sfer życia.'] },
  { term: 'Edging', slug: 'edging', definition: 'Edging to technika polegająca na wielokrotnym doprowadzaniu partnera blisko orgazmu i zatrzymaniu tuż przed — a potem powtarzaniu. Znana też jako "ruined orgasm" w skrajnej formie lub "orgasm control/denial" jako szerszy termin. Frustrujące i intensywnie przyjemne jednocześnie — narastające napięcie sprawia że gdy orgazm w końcu następuje (jeśli Dom na to pozwoli) jest znacznie silniejszy niż normalnie. Edging może trwać od kilkunastu minut do godzin. W kontekście D/s Dom decyduje kiedy Sub może mieć orgazm — lub czy w ogóle. "Permission to cum" (prośba o pozwolenie na orgazm) to popularny element tej dynamiki. Edging jest też techniką terapeutyczną w seksuologii — pomaga mężczyznom z przedwczesnym wytryskiem nauczyć się kontroli.', category: 'BDSM / Kink', examples: ['Edging przez godzinę, a potem permission — intensywność orgazmu jest nieporównywalna.'] },
  { term: 'Consent', slug: 'consent', definition: 'Consent (zgoda) to fundament na którym stoi cały kink i lifestyle — i to co odróżnia BDSM od przemocy. Dobra zgoda ma cztery cechy: jest świadoma (wiesz na co się zgadzasz, masz wszystkie informacje), entuzjastyczna (nie "ok, niech ci będzie" ale "tak, chcę tego"), ongoing (jest sprawdzana w trakcie, nie tylko na początku) i odwołalna (możesz zmienić zdanie w każdej chwili bez konsekwencji). "Może", milczenie, brak oporu — to nie jest zgoda. W BDSM gdzie scena jest zaplanowana i negocjowana zgoda jest złożona: dajesz ją na początku ale Dom jest odpowiedzialny za czuwanie nad nią przez cały czas. Kultura zgody w kink community jest zazwyczaj znacznie bardziej rozwinięta niż w vanilla środowiskach — bo musi być.', category: 'BDSM / Kink', examples: ['"Może" to nie jest zgoda. "Tak, chcę tego" — to jest zgoda.'] },

  // === OGÓLNE / LIFESTYLE ===
  { term: 'Vanilla', slug: 'vanilla', definition: '"Vanilla" to określenie dla konwencjonalnego, monogamicznego seksu i relacji — bez BDSM, CNM ani żadnych "niestandardowych" praktyk. Pochodzi od smaku lodów: vanilla jako "zwykły", "domyślny". W kink i lifestyle community słowo to nie jest pejoratywne — to po prostu descriptor, jak "czarny" i "biały" w fotografii. Vanilla club = zwykły klub nocny. Vanilla relationship = monogamiczny związek bez otwartości. Vanilla sex = seks bez elementów kink. Ważna rzecz: bycie vanilla to w pełni ok i nie wymaga żadnego uzasadnienia. Lifestyle i kink community nie są "lepsze" od vanilla — są po prostu inne. Wiele osób porusza się między vanilla i nie-vanilla w różnych momentach życia, z różnymi partnerami lub w różnych kontekstach.', category: 'Ogólne', examples: ['Nie ma nic złego w vanilla — każdy ma prawo do własnych preferencji.'] },
  { term: 'Play Partner', slug: 'play-partner', definition: 'Play partner to osoba z którą uprawiasz seks lub aktywności kink, bez pełnej relacji romantycznej lub zaangażowania emocjonalnego na poziomie partnerskim. Coś między znajomym a kochankiem — ale z jasno zdefiniowanymi granicami. Regularni play partnerzy znają swoje granice i preferencje, są przetestowani na STI, i czują się ze sobą komfortowo. Relacja play partner może być bardzo cenna i długotrwała bez stawania się "poważnym związkiem". Dla wielu osób w lifestyle jest to preferowany format: stali play partnerzy z którymi jest chemia i zaufanie, bez oczekiwań romantycznych. Ważne: bycie play partnerem nie znaczy że emocje nie istnieją — po prostu są świadomie utrzymywane w konkretnych ramach.', category: 'Ogólne', examples: ['Mamy kilku play partnerów z którymi spotykamy się na eventach — bez romantycznego zaangażowania.'] },
  { term: 'Coming Out (CNM)', slug: 'coming-out-cnm', definition: 'Coming out w kontekście CNM (consensual non-monogamy) to mówienie innym — rodzinie, przyjaciołom, współpracownikom — że jesteś w otwartym związku, poly lub aktywny w lifestyle. Analogia do coming out LGBT+ jest trafna: często podobne emocje (strach przed odrzuceniem, ulga po), podobne reakcje otoczenia (od pełnej akceptacji do niezrozumienia). Wiele osób tego nie robi ze względów praktycznych: praca (dyskryminacja), rodzina (konflikt wartości), dzieci (ochrona prywatności). To jest w pełni ok — nie masz obowiązku outować się nikomu. Decyzja o coming out jest osobista i powinna być przemyślana: kto naprawdę potrzebuje wiedzieć? Co zyskasz, co ryzykujesz?', category: 'Ogólne', examples: ['Coming out przed rodziną był trudny, ale uwolniłam się od kłamstw.'] },
  { term: 'Jealousy vs Envy', slug: 'zazdrość-a-zawiść', definition: 'W CNM i poly community ważne jest rozróżnienie między zazdrością (jealousy) a zawiścią (envy) — bo wymagają różnych reakcji. Zazdrość to strach że stracisz coś co masz: "boję się że gdy spędzi weekend z nią, odejdzie ode mnie" — strach o relację, bezpieczeństwo, miejsce. Zawiść to pragnienie czegoś co ktoś inny ma: "chciałabym mieć tę samą swobodę co on" — informacja o własnych potrzebach. Obie są normalne w CNM — nie znikają magicznie przez sam fakt że "się zgadzasz" na otwartość. Zazdrość jest sygnałem do zbadania własnych potrzeb i lęków, nie rozkazem do działania ani dowodem że coś jest nie tak z relacją. Praca z zazdrością to jedna z najbardziej wartościowych umiejętności w CNM.', category: 'Ogólne', examples: ['Zazdrość to sygnał do zbadania własnych potrzeb — nie rozkaz do działania.'] },
  { term: 'Boundaries', slug: 'boundaries', definition: 'Boundaries (granice) to jasne określenie czego TY potrzebujesz żeby czuć się bezpiecznie i szanowanym — i to ważna różnica od "zasad" (rules). Zasady kontrolują zachowanie partnera: "nie możesz spać z X". Granice opisują Twoje potrzeby: "potrzebuję żebyś testował się na STI co 3 miesiące jeśli mamy niebezpieczny seks". Dobra granica jest konkretna, realistyczna i dotyczy Ciebie — nie jest instrumentem kontroli drugiej osoby. W CNM i lifestyle setting granice są fundamentem bezpiecznej eksploracji. Przykłady zdrowych granic: "zawsze chcę wiedzieć dzień wcześniej że nocujesz poza domem", "nie chcę szczegółów o tym co robisz z innymi, tylko informacji czy jesteś bezpieczny". Granice mogą i powinny ewoluować wraz z relacją.', category: 'Ogólne', examples: ['Moje boundaries: zawsze zabezpieczenie z nowymi osobami, zawsze wiem gdzie jesteś.'] },
  { term: 'OSO (Other Significant Other)', slug: 'oso', definition: 'OSO — Other Significant Other — to termin z poly community oznaczający partnera lub partnerkę Twojego partnera lub partnerki. Neutralne, szanujące określenie dla "drugiego ważnego" w sieci relacji. Przydatne bo unika niezręcznego opisywania relacji ("ta kobieta z którą mój chłopak chodzi") i nadaje tej osobie właściwe miejsce w słowniku. W zdrowej poly sieci OSO bywa osobą z którą masz własną relację — niekoniecznie romantyczną, ale przyjazną i szanującą. Termin pomaga też w rozmowach z innymi: "spotkałam OSO mojego partnera i się zaprzyjaźniłyśmy" jest znacznie jaśniejsze niż długie wyjaśnianie konfiguracji. Powiązane: metamour — dokładnie to samo co OSO, termin używany zamiennie.', category: 'Ogólne', examples: ['Spotkałam OSO mojego chłopaka i od razu przypadłyśmy sobie do gustu.'] },
]

export function getWordOfTheDay() {
  const dayOfYear = Math.floor((Date.now() - new Date(new Date().getFullYear(), 0, 0)) / 86400000)
  return DICTIONARY_TERMS[dayOfYear % DICTIONARY_TERMS.length]
}

export function getTerm(slug) {
  return DICTIONARY_TERMS.find(t => t.slug === slug)
}

export function getTermsByCategory() {
  const cats = {}
  for (const t of DICTIONARY_TERMS) {
    (cats[t.category] ||= []).push(t)
  }
  return cats
}
